pub struct Eff {
    pub qi_pct: f32,

    pub stones: i64,

    pub stones_pct: f32,

    pub dao: f32,

    pub luck: f32,

    pub life_y: f64,

    pub fight: f32,

    pub relic: Option<usize>,

    pub pill: Option<(usize, i32)>,

    pub dy: i64,

    pub contrib: u32, // v1.8.0 D2：宗门贡献（仅现实侧 apply_reff 消费；模拟侧 apply_eff 忽略）

    pub injure: bool,

    pub sect: bool,

    pub lingmai: bool,

    pub comp_fav: i32, // v1.16.17 伴随事件好感通道（模拟侧 apply_eff 消费；comp_fav
                       // 只升不降既定语义——负值在消费口忽略，clamp 100 照道侣赠礼 2642 同款）

    pub death: f32,

    pub special: u8, // 1洞府探索 2天材地宝 3秘境深入 7心魔检定

    pub msg: Vec<String>,

    pub good: bool,
}

impl Eff {
    pub fn new() -> Self {
        Eff {
            qi_pct: 0.0,

            stones: 0,

            stones_pct: 0.0,

            dao: 0.0,

            luck: 0.0,

            life_y: 0.0,

            fight: 0.0,

            relic: None,

            pill: None,

            dy: 0,

            contrib: 0,

            injure: false,

            sect: false,

            lingmai: false,

            comp_fav: 0,

            death: 0.0,

            special: 0,

            msg: Vec::new(),

            good: true,
        }
    }

    // v1.6.0 B：抉择按钮副标签——机制字段的一行式摘要（弹层纵排选项用）
    pub fn eff_desc(&self) -> String {
        let mut parts: Vec<String> = Vec::new();
        if self.qi_pct != 0.0 {
            parts.push(format!("修为+{:.0}%", self.qi_pct * 100.0));
        }
        if self.stones != 0 {
            parts.push(format!(
                "灵石{}{}",
                if self.stones > 0 { "+" } else { "-" },
                fmt_int(self.stones.abs())
            ));
        }
        if self.stones_pct.abs() > 0.001 {
            parts.push(format!("灵石{:+.0}%", self.stones_pct * 100.0));
        }
        if self.dao != 0.0 {
            parts.push(format!("道心+{:.0}", self.dao));
        }
        if self.luck != 0.0 {
            parts.push(format!("气运+{:.0}", self.luck));
        }
        if self.life_y != 0.0 {
            parts.push(format!("寿元+{}载", fmt_num(self.life_y)));
        }
        if self.fight > 0.0 {
            parts.push(format!("交战 ×{:.2}", self.fight));
        }
        if let Some(r) = self.relic {
            parts.push(format!("法宝·{}", RELICS[r].name()));
        }
        if let Some((p, n)) = self.pill {
            parts.push(format!("{}×{}", PILLS[p].name(), n));
        }
        if self.dy != 0 {
            parts.push(format!("道韵+{}", fmt_int(self.dy)));
        }
        if self.contrib > 0 {
            parts.push(format!("贡献+{}", fmt_int(self.contrib as i64)));
        }
        if self.injure {
            parts.push("可能重伤".to_string());
        }
        if self.sect {
            parts.push("拜入宗门".to_string());
        }
        if self.lingmai {
            parts.push("灵脉洞府".to_string());
        }
        if self.death > 0.0 {
            parts.push(format!("身死率{:.0}%", self.death * 100.0));
        }
        if self.special != 0 {
            // v1.16.7 置链臂与新检定臂副标（选项按钮下一行式摘要）
            // v1.16.8 置链臂续编（链4/链5）与检定臂（32..=34）副标
            // v1.16.9 链6（血债血偿）第二段窗口副标
            // v1.16.16 链7..链13 置链臂副标（special 37..=50）：照 20..=36
            // 『续·段名』纪律——段名与 EVENT_NAMES 各链中末段「·续」名同源
            //（37/38=链7 灯花渡舟，39/40=链8 药炉童子，41/42=链9 循册寻仇，
            // 43/44=链10 旧页回声，45/46=链11 劫痕渡客，47/48=链12 书肆换届，
            // 49/50=链13 死当归主）。51/52 为链13 预留窗位（CHAIN13_SPECIAL_HI
            // 上沿），尚无事件占用，落 _ 臂「机缘」兜底
            // v1.16.16 链14（修伞记）置链臂副标：第七窗（53/54 推进臂，
            // 55 为预留窗位落 _ 臂兜底）
            // v1.16.19 链15（观星问岁）置链臂副标：第八窗（56/57 推进臂，
            // 58/59 为预留窗位落 _ 臂兜底）——段名与 EVENT_NAMES 链15
            // 中末段「·续」名同源
            // v1.16.20 链16（剑穗之约）置链臂副标：第九窗（60/61 推进臂——
            // 段名与 EVENT_NAMES 链16 中末段「·续」名同源；62=「一夜结完」
            // 窗内断链收获臂，照 26「镜中赌命」非『续』前缀纪律）
            // v1.16.21 链17（星槎再访）置链臂副标：第十窗（63/64 推进臂——
            // 段名与 EVENT_NAMES 链17 中末段「·续」名同源；65 预留窗位落 _
            // 臂「机缘」兜底）。新检定臂 66 照 32..=34 检定纪律、宿敌遭遇卡
            // 化臂 67/68 照 26/62 非『续』前缀纪律（复审修：漏登曾落「机缘」
            // 兜底，迎战/遁走语义错位）
            // v1.16.22 新检定臂 69 与链18 置链臂副标（第十一窗 70 推进臂——
            // 段名与 EVENT_NAMES 链18 末段「·续」名同源；71/72 预留窗位落
            // _ 臂兜底）
            // v1.16.25 新检定臂 73（空谷叩问 279）照 66/69 检定纪律
            // ——检定槽 73 启用，链19 后续若做改走 74..=76 新窗
            //（v1.16.26 注：74 亦已由检定臂 284 启用，链19 若做改走 75..=76）
            // v1.16.26 新检定臂 74（枯莲夜雨 284）照 66/69/73 检定纪律
            // ——检定槽 74 启用，链19 后续若做改走 75..=76 新窗
            // v1.16.31 新检定臂 75（檐马问风 329）照 66/69/73/74 检定纪律
            // ——检定槽 75 启用，链19 后续若做改走 76 新窗
            // v1.16.37 单2 新检定臂 76（哑缶一声 356）照 66/69/73/74/75 检定纪律
            // ——检定槽 76 启用，75..=76 新窗全部收官：链19 检定窗就此无位
            //（启用即视为放弃该窗作链19 备用；链19 若在近轮规划需另行勘察新窗，
            // 见 batch291 区 :21826 前瞻注同步改写）
            // v1.16.33 单1 副标表通道（--nize）：本 match 收编 textpack——
            // special→N 查表 evtx 一次间接（非帧路径，draw.rs stale 缓存）；
            // 稀疏窗位/未登记值（>76 与槽 0）统一落「机缘」兜底 N，与原
            // _ 臂逐值等价（special_subtitle_fix_tests 全表钉验收）。
            const SPECIAL_SUB: [u16; 81] = [
                2368, 2369, 2370, 2371, 2372, 2373, 2374, 2375,
                2376, 2377, 843, 2378, 2379, 2380, 2381, 2382,
                2383, 2384, 2385, 2368, 2386, 2387, 2388, 2389,
                2390, 2391, 2392, 2393, 2394, 2395, 2396, 2397,
                2398, 2399, 2400, 2401, 2402, 2403, 2404, 2405,
                2406, 2407, 2408, 2409, 2410, 2411, 2412, 2413,
                2414, 2415, 2416, 2368, 2368, 2417, 2418, 2368,
                2419, 2420, 2368, 2368, 2421, 2422, 2423, 2424,
                2425, 2368, 2426, 2427, 2428, 2429, 2430, 2368,
                // v1.16.37 单2：槽 76 由兜底 2368 改登记「受缶一问」N2690（哑缶
                // 一声 356 检定副标，手写行先于正文收编）
                2368, 2431, 2432, 2433, 2690,
                // v1.16.44：槽 77 由兜底 2368 改登记「漏停一问」N2783（漏刻无声
                // 369 检定副标，手写行先于正文收编——75..=76 收官后下一窗）
                2783,
                // v1.16.47：槽 78 由兜底 2368 改登记「卷面候勘」N2838（晒书使巡
                // 377 检定副标，手写行先于正文收编——77 收官后下一窗）
                2838,
                // v1.16.50：槽 79 由兜底 2368 改登记「合卷一问」N2885（收册人问
                // 386 检定副标，手写行先于正文收编——78 收官后下一窗）
                2885,
                // v1.16.53：槽 80 由兜底 2368 改登记「朱点复勘」N2932（朱点回访
                // 395 检定副标，手写行先于正文收编——79 收官后下一窗）
                2932,
            ];
            // v1.16.37 单2 行为修复：槽 76 启用后原 min 钳制会把 >76 的越界值
            // （77/255 等）误钳到 [76] 落「受缶一问」——原 [76]=兜底 N 时此缺陷
            // 被掩盖，special_sub_table_full_sweep 之 77 兜底钉当场红暴露。改
            // .get 越界落兜底 N，恢复表注「>76 恒机缘」语义（0..=76 合法窗位
            // 查表不变，与原 match 逐值等价恢复；v1.16.44 槽 77 启用后合法窗位
            // 0..=77，>77 越界仍恒机缘兜底；v1.16.47 槽 78 启用后合法窗位
            // 0..=78，>78 越界仍恒机缘兜底；v1.16.50 槽 79 启用后合法窗位
            // 0..=79，>79 越界仍恒机缘兜底；v1.16.53 槽 80 启用后合法窗位
            // 0..=80，>80 越界仍恒机缘兜底）
            let s = evtx(SPECIAL_SUB
                .get(self.special as usize)
                .copied()
                .unwrap_or(2368) as usize);
            parts.push(s.to_string());
        }
        if parts.is_empty() {
            "此路平稳无事".to_string()
        } else {
            parts.join(" · ")
        }
    }
}

#[derive(Clone, Copy, PartialEq)]
