impl Life {
    // v1.16.45 多道侣单源小口（防第三份推导漂移）：伴满判定 / 伴名全列 /
    // 某同页人是否在伴（主伴或副伴）。主伴 companion 单槽语义零动。
    pub fn comp_full(&self) -> bool {
        self.companion.is_some() && self.comp_extra.len() >= COMP_MAX - 1
    }

    // 生产读点本轮未用（UI 展示位走 comp_extra.join 单独拼副伴行——主伴主卡
    // 既有单值读点零手术）；钉测 comp_names().len() 计数消费。照 npc.rs
    // add_comp_fav 「定稿 API 保留」先例挂 allow 防构建 warning。
    #[allow(dead_code)]
    pub fn comp_names(&self) -> Vec<&str> {
        let mut v: Vec<&str> = Vec::with_capacity(COMP_MAX);
        if let Some(cn) = self.companion.as_deref() {
            v.push(cn);
        }
        for name in &self.comp_extra {
            v.push(name.as_str());
        }
        v
    }

    pub fn has_comp_idx(&self, i: usize) -> bool {
        let Some(cn) = crate::data::COMPANION_NAMES.get(i) else {
            return false;
        };
        self.companion.as_deref() == Some(*cn)
            || self.comp_extra.iter().any(|x| x == cn)
    }

    // v1.16.46 段十九批 多道侣主/副可辨（勘察六提名二）：缘谱行/图鉴卡行标单源
    // ——多伴态（comp_extra 非空，v1.16.45 新态）下主伴「此生主页」/副伴「此生
    // 同页」；单伴态恒旧文「此生同页」零稳态变化（取舍照勘察六声明：绝对零稳
    // 态变化款——charpanel/gallery 两消费点同批勿半改，v11648_comp_ui_tests 静
    // 态钉看守）；「主」字已在 PANEL_WARM_CHARS 零新字形
    pub fn comp_row_tag(&self, i: usize) -> &'static str {
        if self.comp_extra.is_empty() {
            return "此生同页";
        }
        match crate::data::COMPANION_NAMES.get(i) {
            Some(cn) if self.companion.as_deref() == Some(*cn) => "此生主页",
            _ => "此生同页",
        }
    }

    // 结缘三分支单源口（模拟侧 special17 与现实侧 bond_life_companion 共用）：
    // 返回落位与被轮替的旧名。主伴空→主伴位；主伴有未满→extra 尾；满编→extra[0]
    // FIFO 轮替。comp_fav/gallery 等账面由调用点各自记账，本口只动伴名槽位。
    pub fn bond_slot(&mut self, cn: &str) -> (bool, Option<String>) {
        if self.companion.is_none() {
            self.companion = Some(cn.to_string());
            return (true, None);
        }
        if self.comp_extra.len() < COMP_MAX - 1 {
            self.comp_extra.push(cn.to_string());
            return (false, None);
        }
        let old = self.comp_extra[0].clone();
        self.comp_extra[0] = cn.to_string();
        (false, Some(old))
    }
}

// v1.10.2 成行择道：道途常量与名号（三途分流，分别挂钩战力/周天吐纳/坊市丹药与灵田）
pub const PATH_NONE: u8 = 0;
pub const PATH_SWORD: u8 = 1; // 剑修：战力 ×1.35
pub const PATH_QI: u8 = 2;    // 气修：每载修为 ×1.25、破境率 +0.06
pub const PATH_PILL: u8 = 3;  // 丹修：服丹效果 ×1.35、灵田岁入 ×1.6

pub fn path_name(p: u8) -> &'static str {
    // v1.16.39 遗留清账②：4 臂 N 表收编（SPECIAL_SUB 口径：fn 内 const N 表 +
    // evtx 查表 + .min 钳制）。槽位映射：0=未择道途（原 p=0 落 `_` 兜底同文案）/
    // 1=PATH_SWORD/2=PATH_QI/3=PATH_PILL；PATH_* 常量自 1 起（:744-746）故兜底臂
    // ≠末槽——末槽 4 重复兜底文案「未择道途」（真相源尾行新增 dedup 独立行
    // N2719 与槽 0 各占一行，无同池共享），p≥4 与原 `_` 臂逐值等价；
    // N2716..2719 真相源尾行新增（v1.16.39 遗留清账批），钉测
    // arms_nize_v11639_pins 逐槽 evtx + 全值域映射断言兜底
    const PATH_NAME_NS: [u16; 5] = [2719, 2716, 2717, 2718, 2719];
    evtx(PATH_NAME_NS[(p as usize).min(4)] as usize)
}

// v1.16.40 测试债清偿：灵田岁入共享助手——原「离闭归来静态项」与 advance_time
// 推岁口两处同式重复提取合并（双写即测试债根源）。丹修（path=PATH_PILL）灵田
// 岁入 ×1.6：同一载在线/离线口径一致（漏乘则丹修离闭收益少 60%）；v1.16.40
// 手测自认缺口（game.rs 钩子注释）补自动化，钉测 v11640_hook_tests。
fn lingtian_year_gain(lv: usize, weather: usize, loc: usize, path: u8) -> i64 {
    let path_pill = if path == PATH_PILL { 1.6 } else { 1.0 };
    (LINGTIAN_YIELD[lv.min(3)] as f64 * weather_loc_mult(weather, loc) * path_pill).round() as i64
}

