        g.choose_ending(1);
        assert_eq!(g.ending_show, Some(1));
        assert_eq!(g.ending_anim, 0.6, "终局页开启帧置入场节奏");

        // 未解锁 D 位：卫语句拒绝，不置演出页不置动效
