    // v1.16.31 新功能 3 条良构+门控同源（照 dongfu_batch_gated_by_full_facility
    // 门控单测口径）：天气门控 335（雨 weather==2）/336（灵潮 weather==4）读
    // sim 天时快照——非该天时权重归零、命中入池；337 三设施全满才入池（未满
    // 归零）；立绘钉 335=Npc(1) 胡掌柜/337=Npc(0) 玄诚/336 散件；抉择全链不
    // panic。realm=7 覆盖 mr3/4/6
    #[test]
    fn batch13_gated_cards_well_formed() {
        // 门控同源：非命中天时/未满设施 → 权重归零
        let mut g = sim_game(7, 40.0);
        g.meta.dongfu = [0, 0, 0];
        let (ws, _) = g.sim_event_weights(40.0, 7, false, false, false);
        assert_eq!(ws[335], 0.0, "非雨天 335 不入池");
        assert_eq!(ws[336], 0.0, "非灵潮 336 不入池");
        assert_eq!(ws[337], 0.0, "设施未满 337 不入池");
        // 雨天：335 独入（336 仍 0——雨≠灵潮）
        g.sim.as_mut().unwrap().weather = 2;
        let (ws, _) = g.sim_event_weights(40.0, 7, false, false, false);
        assert!(ws[335] > 0.0, "雨天 335 入池");
        assert_eq!(ws[336], 0.0, "雨天 336 仍不入池（灵潮门独立）");
        // 灵潮：336 独入
        g.sim.as_mut().unwrap().weather = 4;
        let (ws, _) = g.sim_event_weights(40.0, 7, false, false, false);
        assert!(ws[336] > 0.0, "灵潮 336 入池");
        assert_eq!(ws[335], 0.0, "灵潮 335 仍不入池（雨门独立）");
        // 三设施全满：337 入池
        g.meta.dongfu = [3, 3, 3];
        let (ws, _) = g.sim_event_weights(40.0, 7, false, false, false);
        assert!(ws[337] > 0.0, "三设施全满 337 入池");
        // 良构+立绘钉：weather/dongfu 命中态下逐条进卡
        for id in 335..=337usize {
            let mut g = sim_game(7, 40.0);
            g.meta.dongfu = [3, 3, 3];
            {
                let s = g.sim.as_mut().unwrap();
                s.weather = match id {
                    335 => 2,
                    336 => 4,
                    _ => 0,
                };
            }
            g.modal = None;
            g.build_event(id);
            let card = g
                .modal
                .as_ref()
                .unwrap_or_else(|| panic!("事件 {} 无卡臂", id));
            assert_eq!(card.title, EVENT_NAMES[id], "标题双源 id {}", id);
            assert!(!card.text.is_empty());
            assert!(card.opts.len() >= 2, "事件 {} 至少两选项", id);
            for (si, seg) in card.text.split('\n').enumerate() {
                let n = seg.chars().count();
                assert!(
                    n <= 96,
                    "事件 {} 第 {} 段 {} 字超 ≤96 预算（v1.16.53 段七加长批随批放宽 ≤60→≤96 照 batch12 先例款）：{}",
                    id,
                    si + 1,
                    n,
                    seg
                );
            }
            match id {
                335 => assert!(
                    matches!(card.actor, Some(CardActor::Npc(1))),
                    "335 立绘应锁定胡掌柜 Npc(1)"
                ),
                337 => assert!(
                    matches!(card.actor, Some(CardActor::Npc(0))),
                    "337 立绘应锁定玄诚长老 Npc(0)"
                ),
                _ => assert!(card.actor.is_none(), "336 散件不应挂脸"),
            }
            g.choose_option(0); // apply_eff 全链不 panic
        }
    }

    // v1.16.32 单3 扩池 6 条良构+立绘+门控（照 batch12/13 合并口径）：
    // 338 醉道人 Npc(3)/340 宁清霜 Npc(2) 正文钉名双向（named_cards 同款半边
    // 随批）；339 伴随白名单无伴不入池；340 雾门 weather==3；342 老年×伴双门
    // 控（无伴或未到暮年归零）；341 w1 稀有；343 恶缘散件；抉择全链不 panic
    #[test]
    fn batch14_cards_well_formed() {
        // 复审必修修复：原写 338..=344 多含越界 id344（N_EVENTS=344 有效 id 仅
        // 0..=343；build_event 空臂 _=>{} 无条件置卡后 text 空、断言必红）——
        // 批尾 id 343 封口照 batch13 335..=337 先例
        for id in 338..=343usize {
            let mut g = sim_game(7, 40.0);
            g.meta.dongfu = [3, 3, 3];
            {
                let s = g.sim.as_mut().unwrap();
                s.weather = match id {
                    340 => 3,
                    _ => 0,
                };
                if id == 342 {
                    s.lifespan = s.age + 5.0; // 暮年门：余量 ≤ ELDER_LEFT_YEARS
                }
                if id == 339 {
                    s.companion = Some(COMPANION_NAMES[0].to_string());
                }
            }
            g.modal = None;
            g.build_event(id);
            let card = g
                .modal
                .as_ref()
                .unwrap_or_else(|| panic!("事件 {} 无卡臂", id));
            assert_eq!(card.title, EVENT_NAMES[id], "标题双源 id {}", id);
            assert!(!card.text.is_empty());
            assert!(card.opts.len() >= 2, "事件 {} 至少两选项", id);
            for (si, seg) in card.text.split('\n').enumerate() {
                let n = seg.chars().count();
                // v1.16.51 段八加长批随批：段预算 ≤60→≤96（照 v1.16.50 batch12
                // 放宽先例——92px 3 行安全线内 ≤96；运行期下界钉另落
                // v11663_len8_9_batch_tests）
                assert!(
                    n <= 96,
                    "事件 {} 第 {} 段 {} 字超 ≤96 预算：{}",
                    id,
                    si + 1,
                    n,
                    seg
                );
            }
            match id {
                338 => {
                    assert!(
                        matches!(card.actor, Some(CardActor::Npc(3))),
                        "338 立绘应锁定醉道人 Npc(3)"
                    );
                    assert!(card.text.contains("醉道人"), "338 正文钉名");
                }
                340 => {
                    assert!(
                        matches!(card.actor, Some(CardActor::Npc(2))),
                        "340 立绘应锁定宁清霜 Npc(2)"
                    );
                    assert!(card.text.contains("宁清霜"), "340 正文钉名");
                }
                339 | 342 => assert!(
                    matches!(card.actor, Some(CardActor::Comp(0))),
                    "{} 伴随/老年伴卡立绘反查 Comp(0)",
                    id
                ),
                341 => assert!(card.rare, "341 w1 应入稀有区"),
                _ => assert!(card.actor.is_none() && !card.rare, "{} 散件不挂脸非稀有", id),
            }
            g.choose_option(0); // apply_eff 全链不 panic
        }
        // 门控同源：340 非雾不入池/入池；339 无伴不入池；342 无伴或未暮年不入池
        let mut g = sim_game(7, 40.0);
        g.meta.dongfu = [3, 3, 3];
        let (ws, _) = g.sim_event_weights(40.0, 7, false, false, false);
        assert_eq!(ws[340], 0.0, "非雾天 340 不入池");
        assert!(ws[338] > 0.0, "mr7 命中 338 入池");
        g.sim.as_mut().unwrap().weather = 3;
        // 门禁修复：本调用 comp=true（339 在伴随白名单，无伴恒 0——原 comp=false
        // 调用下断「有伴 339」恒红；342 未暮年归零不受 comp 位影响）
        let (ws, _) = g.sim_event_weights(40.0, 7, false, false, true);
        assert!(ws[340] > 0.0, "雾天 340 入池");
        assert_eq!(ws[342], 0.0, "未暮年 342 不入池");
        assert!(ws[339] > 0.0, "有伴 339 入池");
        g.sim.as_mut().unwrap().lifespan = g.sim.as_ref().unwrap().age + 5.0;
        let (ws, _) = g.sim_event_weights(40.0, 7, false, false, true);
        assert!(ws[342] > 0.0, "暮年有伴 342 入池");
        let (ws, _) = g.sim_event_weights(40.0, 7, false, false, false);
        assert_eq!(ws[339], 0.0, "无伴 339 不入池");
        assert_eq!(ws[342], 0.0, "暮年无伴 342 仍不入池");
    }

    // v1.16.33 单3 扩池 5 条良构+立绘+门控（照 batch14 合并口径）：
    // 344 伴随白名单 Comp 立绘（无伴不入池）；345 mr7 恶散件；346 晴门
    // weather==0；347 w1 稀有散件；348 老年×伴双门控 Comp 立绘（无伴或未暮年
    // 归零）；抉择全链不 panic；批尾 348 封口（勿 ..=349，batch14 复审注先例）
    #[test]
    fn batch15_cards_well_formed() {
        for id in 344..=348usize {
            let mut g = sim_game(7, 40.0);
            {
                let s = g.sim.as_mut().unwrap();
                s.weather = match id {
                    346 => 0,
                    _ => 2,
                };
                if id == 344 || id == 348 {
                    s.companion = Some(COMPANION_NAMES[0].to_string());
                }
                if id == 348 {
                    s.lifespan = s.age + 5.0; // 暮年门：余量 ≤ ELDER_LEFT_YEARS
                }
            }
            g.modal = None;
            g.build_event(id);
            let card = g
                .modal
                .as_ref()
                .unwrap_or_else(|| panic!("事件 {} 无卡臂", id));
            assert_eq!(card.title, EVENT_NAMES[id], "标题双源 id {}", id);
            assert!(!card.text.is_empty());
            assert!(card.opts.len() >= 2, "事件 {} 至少两选项", id);
            for (si, seg) in card.text.split('\n').enumerate() {
                let n = seg.chars().count();
                // v1.16.51 段九加长批随批：段预算 ≤60→≤96（照 v1.16.50 batch12
                // 放宽先例同款；运行期下界钉另落 v11663_len8_9_batch_tests）
                assert!(
                    n <= 96,
                    "事件 {} 第 {} 段 {} 字超 ≤96 预算：{}",
                    id,
                    si + 1,
                    n,
                    seg
                );
            }
            match id {
                344 | 348 => assert!(
                    matches!(card.actor, Some(CardActor::Comp(0))),
                    "{} 伴随/老年伴卡立绘反查 Comp(0)",
                    id
                ),
                347 => assert!(card.rare, "347 w1 应入稀有区"),
                _ => assert!(card.actor.is_none() && !card.rare, "{} 散件不挂脸非稀有", id),
            }
            // v1.16.33 复审必修②回归钉：五条徽标臂位全钉——348 老年臂（漏登记
            // 落「遭遇」即红，v1.16.26 已修类）、344 伴随白名单臂、347 稀有臂、
            // 345/346 默认遭遇臂（防误挂老年/章节臂的负向钉）
            let badge = crate::gallery::event_badge(id).0;
            assert_eq!(
                badge,
                match id {
                    344 => "伴随",
                    347 => "稀有",
                    348 => "老年",
                    _ => "遭遇",
                },
                "事件 {} 徽标臂位漂移: {}",
                id,
                badge
            );
            g.choose_option(0); // apply_eff 全链不 panic
        }
        // 门控同源：344 无伴不入池/有伴入池（mr7 需 realm7）；346 非晴不入池/
        // 晴入池（mr3 需 realm3）；348 未暮年或无伴不入池、暮年有伴入池（mr6）
        let mut g = sim_game(7, 40.0);
        let (ws, _) = g.sim_event_weights(40.0, 7, false, false, false);
        assert_eq!(ws[344], 0.0, "无伴 344 不入池");
        g.sim.as_mut().unwrap().companion = Some(COMPANION_NAMES[0].to_string());
        let (ws, _) = g.sim_event_weights(40.0, 7, false, false, true);
        assert!(ws[344] > 0.0, "有伴 344 入池");
        let mut g2 = sim_game(3, 40.0);
        g2.sim.as_mut().unwrap().weather = 2; // Life 默认 weather=0 晴——非晴前置须显式改雨
        let (ws2, _) = g2.sim_event_weights(40.0, 3, false, false, false);
        assert_eq!(ws2[346], 0.0, "非晴 346 不入池");
        g2.sim.as_mut().unwrap().weather = 0;
        let (ws2, _) = g2.sim_event_weights(40.0, 3, false, false, false);
        assert!(ws2[346] > 0.0, "晴 346 入池");
        let mut g3 = sim_game(6, 40.0);
        g3.sim.as_mut().unwrap().companion = Some(COMPANION_NAMES[0].to_string());
        let (ws3, _) = g3.sim_event_weights(40.0, 6, false, false, true);
        assert_eq!(ws3[348], 0.0, "未暮年 348 不入池");
        g3.sim.as_mut().unwrap().lifespan = g3.sim.as_ref().unwrap().age + 5.0;
        let (ws3, _) = g3.sim_event_weights(40.0, 6, false, false, true);
        assert!(ws3[348] > 0.0, "暮年有伴 348 入池");
        let (ws3, _) = g3.sim_event_weights(40.0, 6, false, false, false);
        assert_eq!(ws3[348], 0.0, "暮年无伴 348 仍不入池");
        // 345/347 无门控：mr 达标即入池（mr7 恶散件 / mr2 稀有）
        let mut g4 = sim_game(7, 40.0);
        g4.recent_events.clear();
        let (ws4, _) = g4.sim_event_weights(40.0, 7, false, false, false);
        assert!(ws4[345] > 0.0, "mr7 345 入池");
        let mut g5 = sim_game(2, 40.0);
        g5.recent_events.clear();
        let (ws5, _) = g5.sim_event_weights(40.0, 2, false, false, false);
        assert!(ws5[347] > 0.0, "mr2 347 入池");
    }

    // v1.16.34 单3 扩池批 2 条段十良构+门控抽检（照 batch15 模板：双门控 349
    // 无伴归零/有伴未暮年归零/暮年有伴入池（mr7 需 realm7）；云门 350 weather≠1
    // 归零/==1 入池（mr6 需 realm6）；卡面 title 双源/正文非空/两选项/special
    // 恒 0/抉择 apply_eff 全链不 panic；批尾 350 封口勿 ..=351 照 batch14/15 注）
    #[test]
    fn batch16_cards_well_formed() {
        // 门控抽检：349 老年×伴双门控（mr7；第 5 参 comp 照 batch15 348 同款——
        // 双门控读 comp 参数与 sim 暮年态双条件，入池断言须 comp=true）
        let mut g = sim_game(7, 40.0);
        let (ws, _) = g.sim_event_weights(40.0, 7, false, false, false);
        assert_eq!(ws[349], 0.0, "无伴 349 不入池");
        g.sim.as_mut().unwrap().companion = Some(COMPANION_NAMES[0].to_string());
        let (ws, _) = g.sim_event_weights(40.0, 7, false, false, true);
        assert_eq!(ws[349], 0.0, "有伴未暮年 349 不入池");
        g.sim.as_mut().unwrap().lifespan = g.sim.as_ref().unwrap().age + 5.0;
        let (ws, _) = g.sim_event_weights(40.0, 7, false, false, true);
        assert!(ws[349] > 0.0, "暮年有伴 349 入池");
        // 门控抽检：350 云门（mr6）
        let mut g2 = sim_game(6, 40.0);
        g2.recent_events.clear();
        {
            let s = g2.sim.as_mut().unwrap();
            s.weather = 2; // 雨——非云
        }
        let (ws2, _) = g2.sim_event_weights(40.0, 6, false, false, false);
        assert_eq!(ws2[350], 0.0, "非云 350 不入池");
        {
            let s = g2.sim.as_mut().unwrap();
            s.weather = 1;
        }
        let (ws2, _) = g2.sim_event_weights(40.0, 6, false, false, false);
        assert!(ws2[350] > 0.0, "云天 350 入池");
        // 卡面良构（349 以暮年有伴进卡；350 以云天进卡）
        for id in [349usize, 350] {
            let mut g = if id == 349 {
                let mut g = sim_game(7, 40.0);
                g.meta.chap_done = 0x1FF;
                {
                    let s = g.sim.as_mut().unwrap();
                    s.companion = Some(COMPANION_NAMES[0].to_string());
                    s.lifespan = s.age + 5.0;
                }
                g
            } else {
                let mut g = sim_game(6, 40.0);
                g.meta.chap_done = 0x1FF;
                g.sim.as_mut().unwrap().weather = 1;
                g
            };
            g.modal = None;
            g.build_event(id);
            let card = g
                .modal
                .as_ref()
                .unwrap_or_else(|| panic!("事件 {} 无卡臂", id));
            assert_eq!(card.title, EVENT_NAMES[id], "标题双源 id {}", id);
            assert!(!card.text.is_empty());
            assert!(card.opts.len() >= 2, "事件 {} 至少两选项", id);
            for (label, e) in &card.opts {
                assert_eq!(e.special, 0, "事件 {} 选项「{}」special 非零", id, label);
            }
            g.choose_option(0); // apply_eff 全链不 panic（sync_save 仅置脏不落盘）
        }
    }

    // v1.16.35 单3 扩池批 2 条段十一良构+门控抽检（照 batch16 模板：白名单
    // 351 无伴归零/有伴 mr5 入池；稀有 352 无门控 mr6 直入（w1）；卡面 title
    // 双源/正文非空/两选项/special 恒 0/351 Comp 卡正文钉名（文-脸同源照
    // named_cards_11634 款）/抉择 apply_eff 全链不 panic；批尾 352 封口勿
    // ..=353 照 batch14/15 注）
    #[test]
    fn batch17_cards_well_formed() {
        // 门控抽检：351 伴随白名单（mr5）
        let mut g = sim_game(5, 40.0);
        g.recent_events.clear();
        let (ws, _) = g.sim_event_weights(40.0, 5, false, false, false);
        assert_eq!(ws[351], 0.0, "无伴 351 不入池");
        g.sim.as_mut().unwrap().companion = Some(COMPANION_NAMES[0].to_string());
        let (ws, _) = g.sim_event_weights(40.0, 5, false, false, true);
        assert!(ws[351] > 0.0, "有伴 351 入池");
        // 门控抽检：352 稀有散件无门控（mr6 直入）
        let mut g2 = sim_game(6, 40.0);
        g2.recent_events.clear();
        let (ws2, _) = g2.sim_event_weights(40.0, 6, false, false, false);
        assert!(ws2[352] > 0.0, "352 稀有无门控直入池");
        // 卡面良构（351 以有伴进卡；352 直进）
        for id in [351usize, 352] {
            let mut g = sim_game(if id == 351 { 5 } else { 6 }, 40.0);
            g.meta.chap_done = 0x1FF;
            if id == 351 {
                g.sim
                    .as_mut()
                    .unwrap()
                    .companion = Some(COMPANION_NAMES[0].to_string());
            }
            g.modal = None;
            g.build_event(id);
            let card = g
                .modal
                .as_ref()
                .unwrap_or_else(|| panic!("事件 {} 无卡臂", id));
            assert_eq!(card.title, EVENT_NAMES[id], "标题双源 id {}", id);
            assert!(!card.text.is_empty());
            assert!(card.opts.len() >= 2, "事件 {} 至少两选项", id);
            if id == 351 {
                assert!(
                    card.text.contains(COMPANION_NAMES[0]),
                    "351 正文须具名道侣（文-脸同源）"
                );
            }
            for (label, e) in &card.opts {
                assert_eq!(e.special, 0, "事件 {} 选项「{}」special 非零", id, label);
            }
            g.choose_option(0); // apply_eff 全链不 panic（sync_save 仅置脏不落盘）
        }
    }

