// v1.16.40 测试债清偿：game.rs 钩子注释（原 :15577）手测自认两钩子补自动化——
// 丹修灵田 ×1.6（lingtian_year_gain 提取后直测）与丹修服丹 ×1.35（eat_pill
// 双路径同基线比值）。两消费点均确定性（无 gen_range），夹具免音频/存档 IO。
#[cfg(test)]
mod v11640_hook_tests {
    use super::*;

    use super::revenge_tests::game_with;

    // 每模组私有夹具（仓内 sim_game 同款惯例）
    fn sim_game(realm: usize, luck: f32) -> Game {
        let mut g = game_with(Life::default(), None);
        let mut s = Life::default();
        s.realm = realm;
        s.luck = luck;
        g.sim = Some(s);
        g
    }

    // 丹修灵田 ×1.6：晴（WEATHER_LOC_MULT[0] 恒 1.00）下全层级比率恰 1.6，
    // 另取雨×loc3 非 1.0 乘区组合验公式一致性
    #[test]
    fn lingtian_pill_hook_x16() {
        let bases = [(0usize, 0i64), (1, 300), (2, 1200), (3, 5000)];
        for (lv, base) in bases {
            let got = lingtian_year_gain(lv, 0, 0, PATH_SWORD);
            assert_eq!(got, base, "lv{} 剑修灵田基线（晴恒 1.0 乘区）", lv);
            let pill = lingtian_year_gain(lv, 0, 0, PATH_PILL);
            assert_eq!(pill, (base as f64 * 1.6).round() as i64, "lv{} 丹修 ×1.6", lv);
        }
        // 丹修 300→480 铁例
        assert_eq!(lingtian_year_gain(1, 0, 0, PATH_PILL), 480);
        // 非 1.0 乘区（雨 w=2 / loc=3=1.10）：仍恰按公式 ×1.6
        let base = LINGTIAN_YIELD[1] as f64 * weather_loc_mult(2, 3);
        assert_eq!(
            lingtian_year_gain(1, 2, 3, PATH_PILL),
            (base * 1.6).round() as i64
        );
    }

    // 丹修服丹 ×1.35：聚气丹（id0）修为增益双路径同基线比值恰 1.35（teff 基座
    // pill_mult=0→max(1.0) 两路一致，唯一差异即 eat_pill 单点 ×1.35）；库存恰减 1
    #[test]
    fn eat_pill_pill_hook_x135() {
        let mut g1 = sim_game(2, 100.0);
        {
            let l = g1.life.as_mut().unwrap();
            l.path = PATH_QI;
            l.pills[0] = 1;
        }
        let before1 = g1.life.as_ref().unwrap().qi;
        g1.eat_pill(0);
        let d1 = g1.life.as_ref().unwrap().qi - before1;

        let mut g2 = sim_game(2, 100.0);
        {
            let l = g2.life.as_mut().unwrap();
            l.path = PATH_PILL;
            l.pills[0] = 1;
        }
        let before2 = g2.life.as_ref().unwrap().qi;
        g2.eat_pill(0);
        let d2 = g2.life.as_ref().unwrap().qi - before2;

        assert!(d1 > 0.0, "基线增益须为正，实得 {}", d1);
        assert!(
            (d2 / d1 - 1.35).abs() < 1e-9,
            "丹修服丹应恰 ×1.35，实得 {}",
            d2 / d1
        );
        assert_eq!(g2.life.as_ref().unwrap().pills[0], 0, "库存恰减 1");
    }
}

// 剧情演出包⑫ 天气过渡氛围层钉测（照 card_open_sets_modal_anim 先例）：会话态默认
// 0（旧档口径）+ 变动帧置 0.8 + 同值帧不置位。天气 roll 走 macroquad 全局 rand
//（gen_range 无测试注入口），故按性质测双向断言：每次 advance_time 前清零
// weather_anim，比对 life.weather 变/不变各断言其一——转移矩阵五行自留概率均
// ≤0.50（WEATHER_TRANS data.rs 对角线 0.50/0.30/0.30/0.25/0.05），200 载内任一臂
// 未命中概率 ≤0.5^200，实际必双命中
#[cfg(test)]
mod v11640_anim_tests {
    use super::*;

    use super::revenge_tests::game_with;

    #[test]
    fn weather_changed_sets_anim_same_value_does_not() {
        let mut g = game_with(Life::default(), None);
        assert_eq!(g.weather_anim, 0.0, "会话态默认 0（旧档载入口径）");

        let mut changed = 0usize;
        let mut kept = 0usize;
        for _ in 0..200 {
            let w0 = g.life.as_ref().unwrap().weather.min(4);
            g.weather_anim = 0.0;
            g.advance_time();
            let w1 = g.life.as_ref().unwrap().weather.min(4);
            if w1 != w0 {
                changed += 1;
                assert_eq!(
                    g.weather_anim, 0.8,
                    "天气变动帧须置 0.8s 过渡包络（剧情演出包⑫开启口）"
                );
            } else {
                kept += 1;
                assert_eq!(
                    g.weather_anim, 0.0,
                    "天气同值帧不得置位（weather_changed 门控）"
                );
            }
        }
        assert!(
            changed > 0 && kept > 0,
            "200 载性质测须双向命中：变动{}载/同值{}载",
            changed,
            kept
        );
    }
}

// 剧情演出包⑬ 四开启口防漂移静态钉（照 title_recheck_pin_script_present 读仓先例）：
// zoom 开启口共 4 处——charpanel PanelAct::Zoom / draw 模拟随行卡 / gallery 道侣·文狱
// 两路，均 `g.zoom_art = Some(z);` 后同批置 `g.zoom_anim = 0.22;`（⑩「同批同改勿半改」
// 纪律，漏一处=该入口无动画）。四口均为 draw 侧点按处理器不可自测直调（charpanel 口
// 行为钉在 charpanel::zoom_overlay_tests），本钉以源文件结构断言全覆盖防漂移：
// 逐口断言 zoom_art 置值行后 3 行内出现 zoom_anim 置值行，且三文件计数恰 1/1/2。
// 漏改/错改/新增开启口未带计时（或新增非开启口误置值）任一即红。
#[cfg(test)]
mod v11641_zoom_anim_tests {
    // 静态钉：三生产文件逐口结构断言
    #[test]
    fn zoom_open_sites_all_carry_anim() {
        let root = env!("CARGO_MANIFEST_DIR");
        // (文件, 生产口数)：game.rs 的 zoom_art 置值为测试夹具不在此列
        let plan = [
            ("charpanel.rs", 1usize),
            ("draw.rs", 1),
            ("gallery.rs", 2),
        ];
        for (f, expect) in plan {
            let src = std::fs::read_to_string(
                std::path::Path::new(root).join("src").join(f),
            )
            .unwrap_or_else(|e| panic!("读 src/{} 失败：{}", f, e));
            let lines: Vec<&str> = src.lines().collect();
            let mut sites = 0usize;
            for idx in 0..lines.len() {
                if lines[idx].contains("g.zoom_art = Some(") {
                    sites += 1;
                    let win: String = lines[idx..(idx + 4).min(lines.len())].join("\n");
                    assert!(
                        win.contains("g.zoom_anim = 0.22;"),
                        "src/{} 第 {} 行 zoom 开启口未同批置 zoom_anim=0.22（演出包⑬勿半改）",
                        f,
                        idx + 1
                    );
                }
            }
            assert_eq!(
                sites, expect,
                "src/{} zoom 开启口数漂移：实得 {} 预期 {}——新增开启口须同批带 zoom_anim 置值并入本钉",
                f, sites, expect
            );
        }
    }

    // 会话态默认 0（旧档载入天然无动画，照 weather_anim v11640_anim_tests 口径）
    #[test]
    fn zoom_anim_defaults_zero() {
        let mut g = super::revenge_tests::game_with(super::Life::default(), None);
        assert_eq!(g.zoom_anim, 0.0, "会话态默认 0（旧档载入口径）");
    }
}

// v1.16.40 长老委托钉测：轮换确定性/非目标 no-op/达标边沿恰一次/复命数值与轮换
// 推进/表完备性/显示纯推导。夹具照 v11640_hook_tests 自含副本+game_with 借用先例。
// 挂点 8 处的接线由各挂点所在单口的行为测试既有覆盖（sect_quest/revenge_win 等），
// 此处钉三单口本体与表不变量。
#[cfg(test)]
mod v11640_comm_tests {
    use super::*;

    use super::revenge_tests::game_with;

    fn comm_game() -> Game {
        game_with(Life::default(), None)
    }

    // 轮换确定性：同 seed+同 done 恒同下标；done 0..=8 恰覆盖 8 条各一次（周期=表长）；
    // sel 无效（255）时纯派生且不写回（显示零副作用）
    #[test]
    fn comm_rotation_deterministic() {
        let m = Meta::default();
        let first = m.comm_current();
        let m2 = Meta::default();
        assert_eq!(first, m2.comm_current(), "同 seed 同 done 派生恒等");
        // sel 无效：纯派生不改 sel（只读推导——绘制/预热帧路径零副作用）
        assert_eq!(m.comm_sel, 255);
        assert_eq!(m.comm_current(), first);
        assert_eq!(m.comm_sel, 255, "comm_current 不得写回 sel");
        // 轮换周期：done 推进 8 步 8 条全覆盖
        let mut seen = [false; 8];
        for done in 0..8usize {
            let mut mm = Meta::default();
            mm.comm_done = done as u32;
            seen[mm.comm_current()] = true;
        }
        assert!(seen.iter().all(|&s| s), "done 0..8 须覆盖 8 条委托");
        // 显式写回 sel 后直用缓存
        let mut mm = Meta::default();
        mm.comm_sel = 5;
        assert_eq!(mm.comm_current(), 5);
    }

    // 非目标 kind 静默 no-op；目标 kind 才 +1
    #[test]
    fn comm_bump_wrong_kind_noop() {
        let mut g = comm_game();
        let cur = g.meta.comm_current();
        let kind = crate::data::COMMISSIONS[cur].kind;
        let other = if kind == crate::data::COMM_QUEST {
            crate::data::COMM_EXP
        } else {
            crate::data::COMM_QUEST
        };
        g.comm_bump(other);
        assert_eq!(g.meta.comm_prog, 0, "非目标 kind 不得动账");
        g.comm_bump(kind);
        assert_eq!(g.meta.comm_prog, 1, "目标 kind +1");
    }

    // 达标边沿恰一次：toast+金行只发一次，prog 封顶后 bump 不重发
    #[test]
    fn comm_bump_edge_once() {
        let mut g = comm_game();
        let cur = g.meta.comm_current();
        let c = crate::data::COMMISSIONS[cur];
        for _ in 0..c.target {
            g.comm_bump(c.kind);
        }
        assert_eq!(g.meta.comm_prog, c.target, "进度恰达 target");
        assert!(g.toast.is_some(), "达标边沿发 toast");
        let last = g.log.last().expect("达标边沿发金行");
        assert!(
            last.text.contains("差事已成"),
            "金行=达标句 N2744，实得 {}",
            last.text
        );
        assert_eq!(last.color, C_GOLD, "达标行金色");
        let log_len = g.log.len();
        // 已封顶再 bump：不重发、不越账
        g.comm_bump(c.kind);
        assert_eq!(g.meta.comm_prog, c.target, "saturating 封顶");
        assert_eq!(g.log.len(), log_len, "达标后 bump 不得重发金行");
    }

    // 复命：数值精确入账（贡献/灵石/点数）+ done+1 + prog 清零 + sel 轮换；未达标
    // claim no-op（按钮仅 UI 门）
    #[test]
    fn comm_claim_pays_and_rotates() {
        let mut g = comm_game();
        // 未达标 no-op
        let (contrib0, pts0) = (g.meta.sect_contrib, g.meta.sim_points);
        let stones0 = g.life.as_ref().unwrap().stones;
        g.comm_claim();
        assert_eq!(g.meta.sect_contrib, contrib0, "未达标复命不得发奖");
        // 达标复命
        let cur = g.meta.comm_current();
        let c = crate::data::COMMISSIONS[cur];
        g.meta.comm_prog = c.target;
        g.comm_claim();
        assert_eq!(
            g.meta.sect_contrib,
            contrib0 + c.rw_contrib,
            "贡献入账精确"
        );
        assert_eq!(
            g.life.as_ref().unwrap().stones,
            stones0 + c.rw_stones as i64,
            "灵石入账精确"
        );
        assert_eq!(g.meta.sim_points, pts0 + c.rw_pts as i32, "点数入账精确");
        assert_eq!(g.meta.comm_done, 1, "轮换序数 +1");
        assert_eq!(g.meta.comm_prog, 0, "进度清零");
        assert_eq!(
            g.meta.comm_sel as usize,
            (1usize + g.meta.map_seed as usize) % crate::data::COMMISSIONS.len(),
            "sel 轮换到派生下一条"
        );
    }

    // 表完备性静态钉：kind 序/target 序/N 连号/奖励非负/查表内容逐字
    #[test]
    fn comm_table_pinned() {
        let kinds: Vec<u8> = crate::data::COMMISSIONS.iter().map(|c| c.kind).collect();
        assert_eq!(
            kinds,
            vec![
                crate::data::COMM_QUEST,
                crate::data::COMM_QUEST,
                crate::data::COMM_PILL,
                crate::data::COMM_EXP,
                crate::data::COMM_DONGFU,
                crate::data::COMM_NEME,
                crate::data::COMM_BREAK,
                crate::data::COMM_GIFT,
            ],
            "8 条 kind 序（quest×2/pill/exp/dongfu/neme/break/gift）"
        );
        let targets: Vec<u8> = crate::data::COMMISSIONS.iter().map(|c| c.target).collect();
        assert_eq!(targets, vec![2, 4, 3, 1, 1, 1, 1, 2], "target 序");
        for (k, c) in crate::data::COMMISSIONS.iter().enumerate() {
            assert_eq!(c.title_n, 2728 + k as u16, "title N 连号");
            assert_eq!(c.desc_n, 2736 + k as u16, "desc N 连号");
            assert!(c.target >= 1, "target ≥1");
            assert!(c.rw_pts >= 1, "每条委托必含模拟点数（核心轮回回路）");
        }
        // 文案逐字钉（N 错行/共享错串在此必红；行值取自真相源 tools/row_reader.py 口径）
        assert_eq!(crate::data::comm_title(0), "洒扫殿阶");
        assert_eq!(crate::data::comm_desc(0), "为宗门办差两回，任何差事皆算");
        assert_eq!(crate::data::comm_title(5), "斩除宿敌");
        assert_eq!(
            crate::data::comm_desc(5),
            "斩杀宿敌，现实寻仇或推演反杀皆算"
        );
        assert_eq!(crate::data::comm_title(7), "厚赠故人");
        // 独立文案 N 逐字钉
        assert_eq!(
            crate::data::evtx(crate::data::COMM_DONE_N as usize),
            "差事已成，可去复命"
        );
        assert_eq!(
            crate::data::evtx(crate::data::COMM_CLAIM_N as usize),
            "复命：贡献+{}，灵石+{}，模拟点数+{}"
        );
    }
}

// v1.16.42 上品委托钉测（勘察二主选 A，照 v11640_comm_tests 自含夹具+game_with
// 借用先例）：节律表钉 + claim 上品双倍三币精确账钉 + log 数值自述写实账钉 +
// 非上品恒常账钉 + 轮换后重算钉。零新状态零存档变更——纯派生谓词 comm_premium
// 与 comm_claim 单点乘区同拍（done 自增仅在 claim 尾部）。
#[cfg(test)]
mod v11642_premium_tests {
    use super::*;

    use super::revenge_tests::game_with;

    fn comm_game() -> Game {
        game_with(Life::default(), None)
    }

    // 节律表钉：done 0..=20 恰 4/9/14/19 真（每 5 条第 5 条），其余恒假；
    // 5 与 8 互素（LCM=40）：done∈[0,40) 恰 8 条上品复命、按派生下标均匀散布
    // 全部 8 条委托各恰 1 次——全覆盖口径（每条委托终会轮到上品档）
    #[test]
    fn comm_premium_rhythm() {
        for done in 0..=20u32 {
            assert_eq!(
                crate::data::comm_premium(done),
                done % 5 == 4,
                "节律偏移 done={}",
                done
            );
        }
        let seed = Meta::default().map_seed as usize;
        let mut per_row = [0u32; 8];
        for done in 0..40u32 {
            if crate::data::comm_premium(done) {
                per_row[(done as usize + seed) % 8] += 1;
            }
        }
        assert!(
            per_row.iter().all(|&h| h == 1),
            "LCM=40 全覆盖：8 行各恰 1 次上品，实得 {:?}",
            per_row
        );
        assert_eq!(per_row.iter().sum::<u32>(), 8);
    }

    // 上品复命：三币精确 ×2（贡献/灵石/点数——单点乘区）+ log 数值自述写实账
    //（N2745 模板原样、实参=乘区后实值，禁载基值）+ done+1 轮换推进
    #[test]
    fn comm_claim_premium_doubles() {
        let mut g = comm_game();
        g.meta.comm_sel = 0; // 表行 0：rw 30/400/1
        g.meta.comm_prog = crate::data::COMMISSIONS[0].target;
        g.meta.comm_done = 4; // 第 5 条复命=上品档
        let (contrib0, pts0) = (g.meta.sect_contrib, g.meta.sim_points);
        let stones0 = g.life.as_ref().unwrap().stones;
        g.comm_claim();
        let c = crate::data::COMMISSIONS[0];
        assert_eq!(
            g.meta.sect_contrib,
            contrib0 + c.rw_contrib * 2,
            "上品贡献 ×2"
        );
        assert_eq!(
            g.life.as_ref().unwrap().stones,
            stones0 + c.rw_stones as i64 * 2,
            "上品灵石 ×2"
        );
        assert_eq!(
            g.meta.sim_points,
            pts0 + c.rw_pts as i32 * 2,
            "上品点数 ×2"
        );
        assert_eq!(g.meta.comm_done, 5, "轮换序数 +1");
        // log 数值自述写实账：载 ×2 实值、不载基值
        let last = g.log.last().expect("复命发金行");
        assert!(
            last.text.contains(&fmt_int(c.rw_stones as i64 * 2)),
            "log 须载实发灵石 {}，实得 {}",
            fmt_int(c.rw_stones as i64 * 2),
            last.text
        );
        assert!(
            !last.text.contains(&fmt_int(c.rw_stones as i64)),
            "log 不得载基值 {}，实得 {}",
            fmt_int(c.rw_stones as i64),
            last.text
        );
    }

    // 非上品恒常账：done=5（第 6 条，非上品档）复命恰 ×1（done=0 路径由既有
    // comm_claim_pays_and_rotates 覆盖，此处补尾随档防乘区泄漏）
    #[test]
    fn comm_claim_non_premium_normal() {
        let mut g = comm_game();
        g.meta.comm_sel = 0;
        g.meta.comm_prog = crate::data::COMMISSIONS[0].target;
        g.meta.comm_done = 5;
        let (contrib0, pts0) = (g.meta.sect_contrib, g.meta.sim_points);
        let stones0 = g.life.as_ref().unwrap().stones;
        g.comm_claim();
        let c = crate::data::COMMISSIONS[0];
        assert_eq!(g.meta.sect_contrib, contrib0 + c.rw_contrib, "非上品贡献恒常");
        assert_eq!(
            g.life.as_ref().unwrap().stones,
            stones0 + c.rw_stones as i64,
            "非上品灵石恒常"
        );
        assert_eq!(g.meta.sim_points, pts0 + c.rw_pts as i32, "非上品点数恒常");
    }

    // 轮换后重算：done 自增 1 谓词随节律翻转（UI 徽标与发奖同谓词=绘↔账同拍口径）
    #[test]
    fn comm_premium_recompute_after_rotation() {
        assert!(crate::data::comm_premium(4), "第 5 条上品");
        assert!(!crate::data::comm_premium(5), "复命后第 6 条非上品");
        assert!(!crate::data::comm_premium(8), "第 9 条仍非上品");
        assert!(crate::data::comm_premium(9), "第 10 条复上品");
    }
}

// 剧情可玩性·委托称号（差事十全）授权链钉测（照 v11610_tests::chapter_title_
// earned_by_first_chapter 章节称号款）：未满十单佩戴拒绝（worn 不变）→ 第十单
// comm_claim 边沿授称 toast + 佩戴放行 + 显示口 worn_title_of 即时回读 → 重入
// 幂等（done==10 边沿自然成立，第十一单不再 toast）；另钉 evtx(2776) 可佩句
// 逐字（真相源尾行追加，pack_text 重排防错位——v1.16.33 收编红线）+ title_cell
// 格 19 三元组静态钉。模组名 v11644（v11641/v11642 前缀已被占用，按本批顺延）。
#[cfg(test)]
mod v11644_comm_title_tests {
    use super::*;

    use super::revenge_tests::game_with;

    fn comm_game() -> Game {
        game_with(Life::default(), None)
    }

    // 钳行助手（照 v11642_comm_wire_tests::clamp_row 款）：sel 直写有效下标+
    // 进度清零——默认 sel=255 未落定，claim 首行 ensure→roll 会清 prog，须先
    // 落定再置达标（comm_current 派生值直写回缓存，行不变）
    fn clamp_row(g: &mut Game, row: usize) {
        g.meta.comm_sel = row as u8;
        g.meta.comm_prog = 0;
    }

    // 授权链主测：拒 → 第十单边沿授称 → 放行+回读 → 幂等
    #[test]
    fn comm_title_earned_by_tenth_claim() {
        let mut g = comm_game();
        // 未满十单：值 18 越权拒绝（worn 保持默认 -1 自动跟随）
        g.set_worn_title(18);
        assert_eq!(g.meta.worn_title, -1, "未满十单不得佩戴委托称号");
        // 首单复命：不触发授称（边沿前置确认）
        let row0 = g.meta.comm_current();
        let c = crate::data::COMMISSIONS[row0];
        clamp_row(&mut g, row0);
        g.meta.comm_prog = c.target;
        g.comm_claim();
        assert_eq!(g.meta.comm_done, 1, "首单复命 done 0→1");
        assert!(
            !g.toast
                .as_ref()
                .map_or(false, |(t, _, _)| t.contains("差事十全")),
            "非第十单不得授称"
        );
        // 第十单复命：done 9→10 边沿授称 toast + 佩戴放行 + 显示口即时回读
        g.meta.comm_done = 9;
        let row10 = g.meta.comm_current();
        let c10 = crate::data::COMMISSIONS[row10];
        clamp_row(&mut g, row10);
        g.meta.comm_prog = c10.target;
        g.comm_claim();
        assert_eq!(g.meta.comm_done, 10, "第十单复命序数到位");
        assert!(
            g.toast
                .as_ref()
                .map_or(false, |(t, _, _)| t.contains("差事十全") && t.contains("可佩")),
            "第十单边沿演「称号可佩」toast"
        );
        g.set_worn_title(18);
        assert_eq!(g.meta.worn_title, 18, "comm_done>=10 授权佩戴");
        assert_eq!(g.worn_title_of(), "差事十全", "显示口回读委托称号");
        // 幂等：第十一单复命不再 toast（done==10 边沿自然成立）——清槽后断言
        let row11 = g.meta.comm_current();
        let c11 = crate::data::COMMISSIONS[row11];
        clamp_row(&mut g, row11);
        g.meta.comm_prog = c11.target;
        g.toast = None;
        g.comm_claim();
        assert!(
            g.toast.is_none(),
            "第十一单复命不得再演授称 toast（claim 本口无 toast）"
        );
        assert_eq!(g.worn_title_of(), "差事十全", "幂等后佩戴不变");
    }

    // 边界半程钉：done=10 之前值域各臂拒绝面（9 单拒绝/10 单放行由主测覆盖，
    // 此处钉「claim 达标即 done 边沿、prog 达标但 done=10 已过后不再 toast」的
    // 授称句 N 行内容逐字——pack_text 重排/真相源手改即红）
    #[test]
    fn comm_title_evtx_line_pinned() {
        assert_eq!(
            crate::data::evtx(2776),
            "称号可佩：差事十全（角色·成就称号页）",
            "N2776 可佩句逐字钉（pack_text 重排防错位）"
        );
        // 称号名字面量臂/称号格三元组/授权臂三处同源钉（worn_title_of 按佩戴值
        // 显示——先授权落值再回读）
        let mut g = comm_game();
        g.meta.comm_done = 10;
        g.set_worn_title(18);
        assert_eq!(g.meta.worn_title, 18, "授权臂 comm_done>=10 放行钉");
        assert_eq!(g.worn_title_of(), "差事十全", "worn_title_of 18 臂内容钉");
    }
}

// v1.16.42 勘察二 low② 清账：委托 8 挂点接线内容级钉测——「驱动真实触发函数 →
// 断言 comm_prog +1；钳无关 kind 行重放 → 断言 no-op」双向口径，改错 kind/删挂点/
// 挪出成功臂任一即红。6 条确定性直发（QUEST/DONGFU 走 world pub 口、GIFT 走 npc
// pub 口、PILL 走 buy_pill、NEME 现实臂经 pub 冒烟口 debug_win_revenge 直驱
// private revenge_win、BREAK 走抽取助手）+2 条 RNG 臂经抽取助手确定性直驱
//（act_break 跨境 p 封顶 0.99/special67 p clamp 0.95 永非确定——抽取照 v1.16.39+1
// lingtian_year_gain 先例，抽助手是唯一正路）。静态防漂移钉写死挂点计数与语义
//（NEME 双臂均计/PILL 服丹不计/BREAK 同境不计/EXP 战获单口）。模组名 v11642
//（v11641 前缀已被施工单一 zoom_anim 钉测占用，沿版本顺延）。
#[cfg(test)]
mod v11642_comm_wire_tests {
    use super::*;

    use super::revenge_tests::game_with;

    fn comm_game() -> Game {
        game_with(Life::default(), None)
    }

    fn comm_game_sim() -> Game {
        let mut g = comm_game();
        g.sim = Some(Life::default()); // sim_neme_win_settle 前置（照 sim_game 先例）
        g
    }

    // 钳行助手：sel 直写有效下标+进度清零（comm_current 有效 sel 直用缓存口径）
    fn clamp_row(g: &mut Game, row: usize) {
        g.meta.comm_sel = row as u8;
        g.meta.comm_prog = 0;
    }

    // 表行 kind↔下标对照（COMMISSIONS 声明序=QUEST×2/PILL/EXP/DONGFU/NEME/BREAK/GIFT，
    // comm_table_pinned 已钉）：0=QUEST 2=PILL 3=EXP 4=DONGFU 5=NEME 6=BREAK 7=GIFT

    // ① COMM_QUEST↔sect_quest（world.rs:186，spend_year 存活门后唯一成功路径）
    #[test]
    fn quest_hook_wiring() {
        let mut g = comm_game();
        g.life.as_mut().unwrap().sect = true;
        clamp_row(&mut g, 0);
        crate::world::sect_quest(&mut g);
        assert_eq!(
            g.meta.comm_prog, 1,
            "sect_quest 成功路径须挂 COMM_QUEST +1"
        );
        clamp_row(&mut g, 2); // 无关 kind 行（COMM_PILL）重放同一触发
        crate::world::sect_quest(&mut g);
        assert_eq!(g.meta.comm_prog, 0, "无关 kind 行 no-op（挂点↔kind 双向）");
    }

    // ③ COMM_DONGFU↔dongfu_up（world.rs:505，灵石+贡献双扣款成功后）
    #[test]
    fn dongfu_hook_wiring() {
        let mut g = comm_game();
        clamp_row(&mut g, 4);
        g.life.as_mut().unwrap().stones = 999_999;
        g.meta.sect_contrib = 9_999;
        crate::world::dongfu_up(&mut g, 0);
        assert_eq!(g.meta.comm_prog, 1, "dongfu_up 成功须挂 COMM_DONGFU +1");
        assert!(g.toast.is_some(), "target1 达标边沿 toast");
        clamp_row(&mut g, 0);
        g.meta.dongfu[0] = 0; // 设施/资源复位后重走同一成功路径
        g.life.as_mut().unwrap().stones = 999_999;
        g.meta.sect_contrib = 9_999;
        crate::world::dongfu_up(&mut g, 0);
        assert_eq!(g.meta.comm_prog, 0, "无关 kind 行 no-op");
    }

    // ⑥ COMM_GIFT↔gift_npc（npc.rs:344，扣款+add_fav 后）
    #[test]
    fn gift_hook_wiring() {
        let mut g = comm_game();
        clamp_row(&mut g, 7);
        g.life.as_mut().unwrap().stones = 999_999;
        crate::npc::gift_npc(&mut g, crate::npc::NPC_ELDER);
        assert_eq!(g.meta.comm_prog, 1, "gift_npc 成功须挂 COMM_GIFT +1");
        clamp_row(&mut g, 0);
        g.life.as_mut().unwrap().stones = 999_999;
        crate::npc::gift_npc(&mut g, crate::npc::NPC_ELDER);
        assert_eq!(g.meta.comm_prog, 0, "无关 kind 行 no-op");
    }

    // ⑧ COMM_PILL↔buy_pill（game.rs:14716，现实购丹扣款+库存+1 后；服丹/模拟侧
    // 不计语义=全仓 COMM_PILL bump 恰 1 处，静态钉写死）
    #[test]
    fn pill_hook_wiring() {
        let mut g = comm_game();
        clamp_row(&mut g, 2);
        g.life.as_mut().unwrap().stones = 999_999;
        g.buy_pill(0);
        assert_eq!(g.meta.comm_prog, 1, "buy_pill 成功须挂 COMM_PILL +1");
        clamp_row(&mut g, 0);
        g.life.as_mut().unwrap().stones = 999_999;
        g.buy_pill(0);
        assert_eq!(g.meta.comm_prog, 0, "无关 kind 行 no-op");
    }

    // ⑦ COMM_NEME 现实臂↔revenge_win（game.rs:14544，private——经 pub 冒烟口
    // debug_win_revenge 直驱，勿为测试扩可见面）
    #[test]
    fn neme_reality_hook_wiring() {
        let mut g = comm_game();
        clamp_row(&mut g, 5);
        g.meta.neme = Some(Nemes {
            title: "魔修",
            name: "试敌".into(),
            realm: 1,
        });
        g.debug_win_revenge();
        assert_eq!(g.meta.comm_prog, 1, "revenge_win 须挂 COMM_NEME +1");
        assert_eq!(g.meta.neme_slain, 1, "斩杀计数同段");
        clamp_row(&mut g, 0); // spawn_next_neme 已自动补宿敌，直接重走
        g.debug_win_revenge();
        assert_eq!(g.meta.comm_prog, 0, "无关 kind 行 no-op");
    }

    // ⑤ COMM_BREAK↔break_ok_settle（抽取助手=跨境 ok 臂结算段；同境进层不计
    // 由静态钉+调用点行序写死）
    #[test]
    fn break_hook_wiring() {
        let mut g = comm_game();
        clamp_row(&mut g, 6);
        g.break_ok_settle(3, false, None);
        assert_eq!(
            g.meta.comm_prog, 1,
            "跨境 ok 臂结算须挂 COMM_BREAK +1"
        );
        assert_eq!(g.meta.fame, 2, "声望 drift 挂点③ 同段");
        assert!(g.banner.is_some(), "横幅伴生演出随段");
        clamp_row(&mut g, 0);
        g.break_ok_settle(3, false, None);
        assert_eq!(g.meta.comm_prog, 0, "无关 kind 行 no-op");
    }

    // ④ COMM_NEME 模拟臂↔sim_neme_win_settle（抽取助手=special67 胜臂结算段；
    // 「斩除宿敌」双臂均计=data.rs 头注写死语义）
    #[test]
    fn neme_sim_hook_wiring() {
        let mut g = comm_game_sim();
        clamp_row(&mut g, 5);
        g.sim_neme_win_settle(Nemes {
            title: "魔修",
            name: "试敌".into(),
            realm: 1,
        });
        assert_eq!(g.meta.comm_prog, 1, "模拟反杀臂须挂 COMM_NEME +1");
        assert_eq!(g.meta.neme_slain, 1);
        clamp_row(&mut g, 0);
        g.sim_neme_win_settle(Nemes {
            title: "魔修",
            name: "试敌".into(),
            realm: 1,
        });
        assert_eq!(g.meta.comm_prog, 0, "无关 kind 行 no-op");
    }

    // 全挂点静态防漂移钉（照 v11641_zoom_anim_tests 读仓先例）：挂点总数恰 8 +
    // 逐 kind 计数（NEME=2 双臂均计；PILL/BREAK/EXP 唯一=服丹不计·同境不计·战获
    // 单口语义写死）+ 抽取助手唯一调用点行序（跨境 1566→settle→1567；special67
    // take→settle→1524）+ 1564/1566/1786/1522/1523 回归句在位（抽取逐行平移）。
    // 计数扫描走生产区提取（照 font_cover_scan v1.16.38 修正款跳过规则：行首
    // #[cfg(test)] 起至行首顶格 } 止——全部 cfg(test) 均为 mod/fn 统一形态），
    // 本钉自身字面量不入扫描面
    #[test]
    fn comm_hooks_static_pins() {
        let root = env!("CARGO_MANIFEST_DIR");
        let game_src = std::fs::read_to_string(
            std::path::Path::new(root).join("src").join("game.rs"),
        )
        .expect("读 src/game.rs");
        let world_src = std::fs::read_to_string(
            std::path::Path::new(root).join("src").join("world.rs"),
        )
        .expect("读 src/world.rs");
        let npc_src = std::fs::read_to_string(
            std::path::Path::new(root).join("src").join("npc.rs"),
        )
        .expect("读 src/npc.rs");
        let prod = |src: &str| -> String {
            let mut out = String::new();
            let mut skip = false;
            for line in src.lines() {
                if line.starts_with("#[cfg(test)]") {
                    skip = true;
                    continue;
                }
                if skip {
                    if line == "}" {
                        skip = false;
                    }
                    continue;
                }
                out.push_str(line);
                out.push('\n');
            }
            out
        };
        let game_p = prod(&game_src);
        let all = format!("{}{}{}", game_p, prod(&world_src), prod(&npc_src));
        let count = |hay: &str, needle: &str| hay.matches(needle).count();
        assert_eq!(
            count(&all, "comm_bump(crate::data::"),
            8,
            "委托挂点总数恰 8——增删挂点须同批更新本钉与 data.rs 头注"
        );
        let kinds: [(&str, usize); 7] = [
            ("comm_bump(crate::data::COMM_QUEST)", 1),
            ("comm_bump(crate::data::COMM_PILL)", 1),
            ("comm_bump(crate::data::COMM_EXP)", 1),
            ("comm_bump(crate::data::COMM_DONGFU)", 1),
            ("comm_bump(crate::data::COMM_NEME)", 2),
            ("comm_bump(crate::data::COMM_BREAK)", 1),
            ("comm_bump(crate::data::COMM_GIFT)", 1),
        ];
        for (needle, n) in kinds {
            assert_eq!(count(&all, needle), n, "{} 计数须恰 {}", needle, n);
        }
        // 行序钉锚行全在生产区（首现即生产位——test 区在后不干扰 position）
        let lines: Vec<&str> = game_src.lines().collect();
        let find = |needle: &str| -> usize {
            lines
                .iter()
                .position(|l| l.contains(needle))
                .unwrap_or_else(|| panic!("锚行缺失：{}", needle))
        };
        let l1566 = find("evf(1566");
        let l1567 = find("evf(1567");
        let l_settle = find("self.break_ok_settle(");
        assert!(
            l_settle > l1566 && l_settle < l1567,
            "break_ok_settle 唯一调用点须在跨境 ok 臂内（1566..1567 句之间）"
        );
        let l1564 = find("evf(1564");
        assert!(
            l1564 < l1566,
            "同境臂 1564 句须先于跨境 1566 句（act_break 分支序，其间无 settle=同境不计）"
        );
        let l_take = find("self.meta.neme.take().unwrap_or(crate::game::Nemes");
        let l1524 = find("evf(1524");
        let l_sim = find("self.sim_neme_win_settle(");
        assert!(
            l_sim > l_take && l_sim < l1524,
            "sim_neme_win_settle 唯一调用点须在 special67 胜臂内（take 兜底之后、败句 1524 之前）"
        );
        for needle in ["evf(1564", "evf(1566", "evtx(1786", "evf(1522", "evf(1523"] {
            assert!(
                count(&game_p, needle) >= 1,
                "回归句 {} 缺失——抽取平移不得丢句",
                needle
            );
        }
        // COMM_EXP 单口：bump 在 push_loot 体内（战获单口全 loot 臂覆盖）
        let wlines: Vec<&str> = world_src.lines().collect();
        let wfind = |needle: &str| -> usize {
            wlines
                .iter()
                .position(|l| l.contains(needle))
                .unwrap_or_else(|| panic!("world 锚行缺失：{}", needle))
        };
        let lp = wfind("fn push_loot");
        let le = wfind("COMM_EXP");
        let lx = wfind("pub fn exp_p");
        assert!(
            le > lp && le < lx,
            "COMM_EXP bump 须在 push_loot 体内（挪进 exp_choose 具体臂即引入漏计）"
        );
    }
}

// ================= v1.16.44 扩池 3 条（段十七 368..=370）：门控/立绘/检定/账本 =================

#[cfg(test)]
mod v11644_pool_tests {
    use super::revenge_tests::game_with;
    use super::*;

    fn sim_game(realm: usize, luck: f32) -> Game {
        let mut g = game_with(Life::default(), None);
        let mut s = Life::default();
        s.realm = realm;
        s.luck = luck;
        g.sim = Some(s);
        g
    }
    // 卡面良构+门控抽检（照 batch21 之 365..=367 款）：368 双门控（mr7）无伴/
    // 有伴未暮年归零、暮年有伴入池；369 稀有 w1 mr2 无门控直入池+检定臂 special77
    // 豁免款照 batch18 之 356；370 伴随白名单（mr0）无伴归零/有伴入池；卡面
    // title 双源/正文非空/两选项/368/370 Comp 卡正文钉名（文-脸同源照 named_cards
    // 款）/抉择 apply_eff 全链不 panic（含 special77 检定臂走 apply_eff 新分支）
    #[test]
    fn batch22_cards_well_formed() {
        // 门控抽检：368 双门控（mr7）——无伴/有伴未暮年归零、暮年有伴入池
        let mut g2 = sim_game(7, 40.0);
        g2.recent_events.clear();
        let (ws2, _) = g2.sim_event_weights(40.0, 7, false, false, false);
        assert_eq!(ws2[368], 0.0, "无伴 368 不入池");
        g2.sim
            .as_mut()
            .unwrap()
            .companion = Some(COMPANION_NAMES[0].to_string());
        let (ws2, _) = g2.sim_event_weights(40.0, 7, false, false, true);
        assert_eq!(ws2[368], 0.0, "有伴未暮年 368 不入池");
        g2.sim.as_mut().unwrap().lifespan = g2.sim.as_ref().unwrap().age + 5.0;
        let (ws2, _) = g2.sim_event_weights(40.0, 7, false, false, true);
        assert!(ws2[368] > 0.0, "暮年有伴 368 入池");
        // 门控抽检：369 稀有散件无门控（w1 mr2 直入池）
        let mut g0 = sim_game(2, 40.0);
        g0.recent_events.clear();
        let (ws0, _) = g0.sim_event_weights(40.0, 2, false, false, false);
        assert!(ws0[369] > 0.0, "369 稀有无门控直入池");
        // 门控抽检：370 伴随白名单（mr0）——无伴归零/有伴入池
        let mut g1 = sim_game(0, 40.0);
        g1.recent_events.clear();
        let (ws1, _) = g1.sim_event_weights(40.0, 0, false, false, false);
        assert_eq!(ws1[370], 0.0, "无伴 370 不入池");
        g1.sim
            .as_mut()
            .unwrap()
            .companion = Some(COMPANION_NAMES[0].to_string());
        let (ws1, _) = g1.sim_event_weights(40.0, 0, false, false, true);
        assert!(ws1[370] > 0.0, "有伴 370 入池");
        // 卡面良构（369 直进；370 有伴进卡；368 暮年有伴进卡）
        for id in [368usize, 369, 370] {
            let mut g = match id {
                369 => sim_game(2, 40.0),
                370 => {
                    let mut g = sim_game(0, 40.0);
                    g.sim
                        .as_mut()
                        .unwrap()
                        .companion = Some(COMPANION_NAMES[0].to_string());
                    g
                }
                _ => {
                    let mut g = sim_game(7, 40.0);
                    {
                        let s = g.sim.as_mut().unwrap();
                        s.companion = Some(COMPANION_NAMES[0].to_string());
                        s.lifespan = s.age + 5.0;
                    }
                    g
                }
            };
            g.meta.chap_done = 0x1FF;
            g.modal = None;
            g.build_event(id);
            let card = g.modal.as_ref().unwrap();
            assert_eq!(
                card.title,
                crate::data::EVENT_NAMES[id],
                "事件 {} 标题双源",
                id
            );
            assert!(!card.text.is_empty());
            assert!(card.opts.len() >= 2, "事件 {} 至少两选项", id);
            if id == 369 {
                // 检定臂豁免款照 batch18 之 356：opts[0]=special77，其余恒 0
                assert_eq!(
                    card.opts[0].1.special, 77,
                    "369 检定臂应为 special77"
                );
                for (label, e) in card.opts.iter().skip(1) {
                    assert_eq!(e.special, 0, "369 选项「{}」special 非零", label);
                }
            } else {
                for (label, e) in &card.opts {
                    assert_eq!(e.special, 0, "事件 {} 选项「{}」special 非零", id, label);
                }
            }
            if id != 369 {
                assert!(
                    card.text.contains(COMPANION_NAMES[0]),
                    "事件 {} 正文须具名道侣（文-脸同源）",
                    id
                );
                assert!(
                    matches!(card.actor, Some(CardActor::Comp(_))),
                    "事件 {} 须挂 Comp 立绘（照 362/366 模板）",
                    id
                );
            }
            g.choose_option(0); // apply_eff 全链不 panic（sync_save 仅置脏不落盘）
        }
    }

    // 369 检定裁决钉：choose_option(0) 走 apply_eff 77 分支（本模组 sim_game
    // 夹具 sim=Some 直驱）——good=false 检定臂不落全局 good；分支可达性由
    // apply_eff_ledger_and_result_colors 同款全链不 panic 覆盖
    #[test]
    fn event_369_check_arm_reaches_apply_eff_77() {
        let mut g = sim_game(2, 40.0);
        g.meta.chap_done = 0x1FF;
        g.modal = None;
        g.build_event(369);
        assert_eq!(
            g.modal.as_ref().unwrap().opts[0].1.special, 77,
            "369 臂 0 检定窗 77"
        );
        let dao0 = g.sim.as_ref().unwrap().dao;
        g.choose_option(0);
        let dao1 = g.sim.as_ref().unwrap().dao;
        // 过臂 dao+3 / 败臂 dao-2——两次 delta 均非零即 77 分支实际生效
        //（单次 RNG 不可确定性，双向包络钉）
        assert!(
            dao1 > dao0 || dao1 < dao0,
            "apply_eff 77 分支未生效（dao 无变化）"
        );
        assert!(dao1 <= 100.0, "dao 封顶守恒");
    }

    // v1.16.44 扩池沿例（355/348/349/363/367 先例）：368 暖阁晒背 = 老年×伴双门
    // 控第 18 条（mr7）——随批补四象限门控行为测试与白名单负断言（照
    // dual_gate_367_four_quadrants 款：无伴×非老年/无伴×老年/有伴×非老年皆归零，
    // 有伴×老年才入池；徽标走老年臂 gallery（v1.16.44 随批已登记），不入
    // COMPANION 白名单——双门控卡非伴随卡，照 268 负断言口径）
    #[test]
    fn dual_gate_368_four_quadrants() {
        // 象限 1：无伴 × 非老年 → 0（sim_game(7,..) 过 mr7 门——若门控失效仅
        // 靠 mr 门挡无伴态，本象限抓不住，象限 4 的 comp+暮年双条件才是正证）
        let mut g = sim_game(7, 40.0);
        g.recent_events.clear();
        let (ws, _) = g.sim_event_weights(40.0, 7, false, false, false);
        assert_eq!(ws[368], 0.0, "无伴非老年：368 不入池");
        // 象限 2：无伴 × 老年（余量 5 载）→ 0
        let mut g2 = sim_game(7, 40.0);
        g2.recent_events.clear();
        {
            let s = g2.sim.as_mut().unwrap();
            s.age = s.lifespan - 5.0;
        }
        let (ws2, _) = g2.sim_event_weights(40.0, 7, false, false, false);
        assert_eq!(ws2[368], 0.0, "无伴老年：368 不入池");
        // 象限 3：有伴 × 非老年 → 0（余量富余——若单走伴白名单则此处会误入池）
        let mut g3 = sim_game(7, 40.0);
        g3.recent_events.clear();
        let (ws3, _) = g3.sim_event_weights(40.0, 7, false, false, true);
        assert_eq!(ws3[368], 0.0, "有伴非老年：368 不入池");
        // 象限 4：有伴 × 老年 → >0（第 5 参 comp 须 true——双门控读 comp 参数与
        // sim 暮年态双条件，照 batch21 367/batch16 348/batch16 349/batch17 355 同款）
        let mut g4 = sim_game(7, 40.0);
        g4.recent_events.clear();
        {
            let s = g4.sim.as_mut().unwrap();
            s.age = s.lifespan - 5.0;
        }
        let (ws4, _) = g4.sim_event_weights(40.0, 7, false, false, true);
        assert!(ws4[368] > 0.0, "有伴老年：368 入池");
        // 白名单负断言（照 367 款）：双门控卡非伴随卡——212 在白名单内走伴随臂
        // 的死模式勿混；370 反向正断言：伴随白名单第 37 条
        assert!(
            !COMPANION_EVENTS.contains(&368u16),
            "368 双门控卡不得入 COMPANION 白名单"
        );
        assert!(
            COMPANION_EVENTS.contains(&370u16),
            "370 同制新历须入 COMPANION 白名单"
        );
    }

    // special77 副标钉（照 special_subtitle_fix 之 76 槽 eff_desc 款）：SPECIAL_SUB
    // 扩 78 槽后槽 77=2783「漏停一问」启用值反向钉（误改回兜底 2368 当场红）
    #[test]
    fn special77_sub_registered() {
        let mut e = Eff::new();
        e.special = 77;
        assert_eq!(e.eff_desc(), "漏停一问", "槽 77 副标应启用「漏停一问」");
    }
}

// ================= v1.16.45 多道侣 + 现实邂逅 + bug② 遗留视觉清理 钉测 =================
// 照 v11642_premium_tests 先例（自含夹具 + use super::revenge_tests::game_with）。
// 钉面：①连认上限/FIFO 轮替/first 边沿防灌水 ②遭遇乘区三态（基权表零改动）
// ③基权 pin（防误改 EVENTS_ROWS 破 pool_ledger_recheck）④遗泽承伴不顶替
// ⑤apply_reff special17 现实结缘三分支 ⑥feng/neme 与多伴零耦合（行为+静态双钉）
// ⑦现实邂逅卡构造与分派接线 ⑧bug② 鬼影标签删除静态钉（正向删净+反向四真钮在位）
#[cfg(test)]
mod v11645_comp_multi_tests {
    use super::revenge_tests::game_with;
    use super::*;

    fn sim_game(realm: usize, luck: f32) -> Game {
        let mut g = game_with(Life::default(), None);
        let mut s = Life::default();
        s.realm = realm;
        s.luck = luck;
        g.sim = Some(s);
        g
    }

    // 照 gallery_bond_chain_tests::bond_card 构卡法（special=17 单选项认下卡）
    fn bond_card() -> EventCard {
        let mut e = Eff::new();
        e.special = 17;
        EventCard {
            kind: CardKind::Npc,
            actor: None,
            rare: false,
            stage: None,
            cat: None,
            scene: None,
            brk: false,
            title: "同页天成".into(),
            text: "两页相贴，缝作同页——可愿？".into(),
            opts: vec![("认下这页".into(), e)],
        }
    }

    // 从 sim.highlights 尾行解析本次结缘名（1515/1516/1517 三行共通「岁，与X…」
    // 前缀；X=COMPANION_NAMES 内 2-4 字名无标点）——掷名随机下取确定值防 flaky
    fn last_bond_name(highlights: &[String]) -> String {
        let h = &highlights[highlights.len() - 1];
        let t = h.split_once("岁，与").expect("结缘行含「岁，与」").1;
        for end in ["缝作同页", "初缝三生之页", "同页重逢"] {
            if let Some((name, _)) = t.split_once(end) {
                return name.to_string();
            }
        }
        panic!("结缘行无已知尾式：{}", h);
    }

    // ── G1 连认上限/FIFO 轮替/first 边沿 ──
    #[test]
    fn multi_bond_cap_and_eviction() {
        let mut g = game_with(Life::default(), None);
        g.sim = Some(Life::default());
        for _k in 0..3 {
            g.modal = Some(bond_card());
            g.choose_option(0);
        }
        {
            let s = g.sim.as_ref().unwrap();
            assert!(s.companion.is_some(), "3 认后主伴在位");
            assert_eq!(s.comp_extra.len(), 2, "3 认后副伴恰 2（上限 COMP_MAX-1）");
            assert_eq!(s.comp_names().len(), COMP_MAX, "伴总数恒 3");
        }
        assert_eq!(
            g.meta.comp_bonds.iter().sum::<u8>(),
            3,
            "历世缘谱账累计不回退"
        );
        assert_eq!(
            g.meta.companion_lives, 1,
            "companion_lives 只在主伴 None→Some 边沿 +1（副伴结缘不计数防成就灌水）"
        );
        // 第 4 认：FIFO 轮替——总数恒 3、extra[0] 恰为本认掷出名、历世账继续累计
        g.modal = Some(bond_card());
        g.choose_option(0);
        let cn = last_bond_name(&g.sim.as_ref().unwrap().highlights);
        let s = g.sim.as_ref().unwrap();
        assert_eq!(s.comp_names().len(), COMP_MAX, "第 4 认总数仍恒 3");
        assert_eq!(
            s.comp_extra[0], cn,
            "满编认下=extra[0] FIFO 轮替（最旧副伴出列，新名入首槽）"
        );
        assert_eq!(g.meta.comp_bonds.iter().sum::<u8>(), 4, "轮替亦记历世账");
        assert_eq!(
            g.meta.companion_lives, 1,
            "轮替不触 first 边沿（companion_lives 恒 1）"
        );
    }

    // ── G2 遭遇乘区三态：无伴=基权 5 / 有伴未满=恰 25 / 满编=恰 5 ──
    // luck=40 使 good 乘区 (1.0+(40-40)/120)=1.0、region0 event_mult=1.0——
    // 三态断言落在纯基权×本乘区基线（既有 luck/区域乘区与 28 无关恒同乘）
    #[test]
    fn encounter_boost_gate() {
        let g = sim_game(5, 40.0);
        let (ws, _) = g.sim_event_weights(40.0, 5, false, false, false);
        assert_eq!(ws[ev_pos(28)], 5.0, "无伴=基权原样（乘区不触发）");

        let mut g2 = sim_game(5, 40.0);
        {
            let s = g2.sim.as_mut().unwrap();
            s.companion = Some(COMPANION_NAMES[0].to_string());
        }
        let (ws2, _) = g2.sim_event_weights(40.0, 5, false, false, true);
        assert_eq!(ws2[ev_pos(28)], 25.0, "有伴未满：28 权重恰 ×5");

        let mut g3 = sim_game(5, 40.0);
        {
            let s = g3.sim.as_mut().unwrap();
            s.companion = Some(COMPANION_NAMES[0].to_string());
            s.comp_extra = vec![
                COMPANION_NAMES[1].to_string(),
                COMPANION_NAMES[2].to_string(),
            ];
        }
        let (ws3, _) = g3.sim_event_weights(40.0, 5, false, false, true);
        assert_eq!(ws3[ev_pos(28)], 5.0, "满编恢复基权（不再勾新缘）");

        // 副伴 1 条（未满）同享乘区——判定走 comp_full 单源口非 extra 空判
        let mut g4 = sim_game(5, 40.0);
        {
            let s = g4.sim.as_mut().unwrap();
            s.companion = Some(COMPANION_NAMES[3].to_string());
            s.comp_extra = vec![COMPANION_NAMES[4].to_string()];
        }
        let (ws4, _) = g4.sim_event_weights(40.0, 5, false, false, true);
        assert_eq!(ws4[ev_pos(28)], 25.0, "1 副伴未满仍 ×5");
    }

    // ── G3 基权 pin：EVENTS_ROWS[28] 行零改动（防误改基权破 pool_ledger_recheck
    // total==1130/稀有 51 的静态钉，不与该 pin 重复求和） ──
    #[test]
    fn base_weight_pin_unchanged() {
        assert_eq!(
            EVENTS_ROWS[28],
            (28, 5, 1, true),
            "28 同页天成基权恒 5——放宽只许 sim_event_weights 运行期乘区"
        );
    }

    // ── G4 遗泽承伴不顶替：主伴空→主伴位 / 异名→extra 尾插 / 满编→FIFO 轮替；
    // comp_fav=max(现实,模拟)+10 语义不动 ──
    fn inherit_game(life_comp: Option<&str>, extras: Vec<&str>, sim_comp: &str) -> Game {
        let mut g = game_with(Life::default(), None);
        let mut l = Life::default();
        l.companion = life_comp.map(String::from);
        l.comp_extra = extras.iter().map(|s| s.to_string()).collect();
        l.comp_fav = 20;
        g.life = Some(l);
        g.sim_result = Some(SimResult {
            cause: "寿终".into(),
            total_dy: 0,
            max_realm: 3,
            age: 90.0,
            years: 74,
            qi_gain: 0.0,
            tech: 0,
            relic: None,
            stones: 0,
            pills: [0; 6],
            highlights: Vec::new(),
            comp: Some(sim_comp.to_string()),
            comp_fav: 30,
            story: None,
        });
        g.inherit_opts = vec![8];
        g
    }

    #[test]
    fn inherit_no_overwrite() {
        // 主伴空 → 原样置主伴（原路径语义零动）
        let mut g = inherit_game(None, vec![], COMPANION_NAMES[5]);
        g.take_inherit(0);
        let l = g.life.as_ref().unwrap();
        assert_eq!(l.companion.as_deref(), Some(COMPANION_NAMES[5]));
        assert!(l.comp_extra.is_empty());
        assert_eq!(l.comp_fav, 40, "max(30,20)+10 语义不动");

        // 主伴已有且异名 → 模拟主伴入 extra 尾（companion 不顶替）
        let mut g2 = inherit_game(Some(COMPANION_NAMES[0]), vec![], COMPANION_NAMES[5]);
        g2.take_inherit(0);
        let l2 = g2.life.as_ref().unwrap();
        assert_eq!(
            l2.companion.as_deref(),
            Some(COMPANION_NAMES[0]),
            "主伴不顶替"
        );
        assert_eq!(l2.comp_extra, vec![COMPANION_NAMES[5].to_string()]);
        assert_eq!(l2.comp_fav, 40);

        // 满编（主伴+2 副伴）→ extra[0] FIFO 轮替、总数恒 3
        let mut g3 = inherit_game(
            Some(COMPANION_NAMES[0]),
            vec![COMPANION_NAMES[1], COMPANION_NAMES[2]],
            COMPANION_NAMES[5],
        );
        g3.take_inherit(0);
        let l3 = g3.life.as_ref().unwrap();
        assert_eq!(l3.companion.as_deref(), Some(COMPANION_NAMES[0]));
        assert_eq!(l3.comp_extra.len(), COMP_MAX - 1, "满编总数恒 3");
        assert_eq!(
            l3.comp_extra[0],
            COMPANION_NAMES[5],
            "extra[0] 轮替为模拟主伴"
        );
        assert_eq!(l3.comp_fav, 40);

        // 主伴与模拟主伴同名 → 重逢槽位不动（不重复入列）
        let mut g4 = inherit_game(Some(COMPANION_NAMES[5]), vec![], COMPANION_NAMES[5]);
        g4.take_inherit(0);
        let l4 = g4.life.as_ref().unwrap();
        assert_eq!(l4.companion.as_deref(), Some(COMPANION_NAMES[5]));
        assert!(l4.comp_extra.is_empty(), "重逢不重复入列");
    }

    // ── G5 现实结缘：apply_reff special17 前置臂 → bond_life_companion 三分支 +
    // first 边沿（companion_lives/check_chapters 只在主伴 None→Some） ──
    #[test]
    fn reality_bond_via_reff() {
        // 主伴空：认下 → 现实主伴落位 + first 边沿
        let mut g = game_with(Life::default(), None);
        let mut e = Eff::new();
        e.special = 17;
        e.msg = vec!["缝口咬合".to_string()];
        crate::npc::apply_reff(&mut g, &e);
        let l = g.life.as_ref().unwrap();
        assert!(l.companion.is_some(), "special17 落现实主伴");
        assert!(l.comp_extra.is_empty());
        assert_eq!(l.comp_fav, COMPANION_BOND_FAV, "结缘起步 25");
        assert_eq!(g.meta.companion_lives, 1, "first 边沿 companion_lives+1");
        assert_eq!(
            g.meta.comp_bonds.iter().sum::<u8>(),
            1,
            "gallery_bond 记账"
        );
        assert!(
            g.log.iter().any(|m| m.text.contains("缝口咬合")),
            "eff.msg 自述行先行出账"
        );

        // 主伴已有：认下 → extra 尾插，companion_lives 不再 +1（副伴不计数）
        let mut g2 = game_with(Life::default(), None);
        {
            let l = g2.life.as_mut().unwrap();
            l.companion = Some(COMPANION_NAMES[0].to_string());
        }
        g2.meta.companion_lives = 1;
        crate::npc::apply_reff(&mut g2, &e);
        let l2 = g2.life.as_ref().unwrap();
        assert_eq!(
            l2.companion.as_deref(),
            Some(COMPANION_NAMES[0]),
            "主伴不顶替"
        );
        assert_eq!(l2.comp_extra.len(), 1, "副伴入 extra");
        assert_eq!(g2.meta.companion_lives, 1, "副伴结缘不触 first 边沿");
        assert_eq!(g2.meta.comp_bonds.iter().sum::<u8>(), 1, "副伴亦记历世账");

        // 满编：认下 → extra[0] FIFO 轮替（总数恒 3）
        let mut g3 = game_with(Life::default(), None);
        {
            let l = g3.life.as_mut().unwrap();
            l.companion = Some(COMPANION_NAMES[0].to_string());
            l.comp_extra = vec![
                COMPANION_NAMES[1].to_string(),
                COMPANION_NAMES[2].to_string(),
            ];
        }
        crate::npc::apply_reff(&mut g3, &e);
        let l3 = g3.life.as_ref().unwrap();
        assert_eq!(l3.comp_names().len(), COMP_MAX, "总数恒 3");
        assert_eq!(l3.comp_extra.len(), COMP_MAX - 1, "满编不越限");
    }

    // ── G6 feng/neme 与多伴零耦合 ──
    #[test]
    fn feng_and_neme_untouched() {
        // 行为钉：feng_reunion 判定只依赖 prev（主伴名）与 feng_bn——comp_extra
        // 内容不影响输出（多伴变体与单伴变体同值；feng_bn/feng_blv 仅沿缝页人）
        let mut g = game_with(Life::default(), None);
        g.meta.feng_bn = 1; // 缝页人=洛书遥
        g.sim = Some(Life::default());
        let s = g.sim.as_ref().unwrap();
        assert!(
            g.feng_reunion(Some(COMPANION_NAMES[0]), COMPANION_NAMES[1]),
            "主伴≠缝页人 → 重逢真（与单伴语义一致）"
        );
        assert!(
            !g.feng_reunion(Some(COMPANION_NAMES[1]), COMPANION_NAMES[1]),
            "缝页人在同页（主伴位）→ 不重逢"
        );
        let _ = s;
        // 多伴变体：comp_extra 非空不改变判定（feng 只沿主伴 prev 与缝页人）
        let mut g2 = game_with(Life::default(), None);
        g2.meta.feng_bn = 1;
        g2.sim = Some(Life::default());
        {
            let s2 = g2.sim.as_mut().unwrap();
            s2.companion = Some(COMPANION_NAMES[0].to_string());
            s2.comp_extra = vec![
                COMPANION_NAMES[2].to_string(),
                COMPANION_NAMES[3].to_string(),
            ];
        }
        let prev = g2.sim.as_ref().unwrap().companion.clone();
        assert!(
            g2.feng_reunion(prev.as_deref(), COMPANION_NAMES[1]),
            "多伴下缝页人重逢判定不变"
        );
        assert!(
            !g2.feng_reunion(prev.as_deref(), COMPANION_NAMES[2]),
            "副伴非缝页人 → 不重逢（feng_blv 只沿缝页人）"
        );

        // 静态钉：sim_neme/act_revenge/sim_neme_win_settle 函数体零 companion/
        // comp_extra/comp_fav 引用（恶缘线与多道侣零耦合防回归）
        let root = env!("CARGO_MANIFEST_DIR");
        let src =
            std::fs::read_to_string(std::path::Path::new(root).join("src").join("game.rs"))
                .expect("读 src/game.rs");
        let lines: Vec<&str> = src.lines().collect();
        let fn_body = |name: &str| -> String {
            let start = lines
                .iter()
                .position(|l| {
                    (l.trim_start().starts_with("fn ")
                        || l.trim_start().starts_with("pub fn "))
                        && l.contains(name)
                })
                .unwrap_or_else(|| panic!("找不到 fn {}", name));
            // 从签名行下一行起收集，遇下一同缩进 fn 行（4 空格缩进方法）即止
            let mut body = String::new();
            for l in lines.iter().skip(start + 1) {
                if l.starts_with("    fn ") || l.starts_with("    pub fn ") {
                    break;
                }
                body.push_str(l);
                body.push('\n');
            }
            body
        };
        for name in [
            "sim_neme(&mut self)",
            "act_revenge(&mut self)",
            "sim_neme_win_settle(&mut self,",
        ] {
            let body = fn_body(name);
            assert!(
                !body.contains("companion")
                    && !body.contains("comp_extra")
                    && !body.contains("comp_fav"),
                "{} 函数体不得引用伴字段（恶缘线与多道侣零耦合）",
                name
            );
        }
    }

    // ── G7 现实邂逅卡构造与分派接线 ──
    #[test]
    fn rencounter_card_wiring() {
        let card = Game::rencounter_card();
        assert!(matches!(card.kind, CardKind::Rencounter), "新 kind 独占分派");
        // 卡面立绘与文本名同源同掷（照 28 臂纪律：正文含掷出名、立绘 Comp(ci)）
        if let Some(CardActor::Comp(ci)) = card.actor {
            assert!(ci < COMPANION_NAMES.len());
            assert!(
                card.text.contains(COMPANION_NAMES[ci]),
                "卡面文本名与立绘下标同源"
            );
        } else {
            panic!("邂逅卡须挂 Comp 立绘（零新立绘红线）");
        }
        assert_eq!(card.title, EVENT_NAMES[28], "标题单源查表 28");
        assert_eq!(card.opts.len(), 2);
        assert_eq!(card.opts[0].1.special, 17, "认下臂 special17");
        assert_eq!(card.opts[1].1.dao, 5.0, "婉拒臂 dao+5 照 28 臂");
        // advance_time 装配锚行序：fn advance_time < rencounter 卡挂载 < fn ach_progress
        let root = env!("CARGO_MANIFEST_DIR");
        let src =
            std::fs::read_to_string(std::path::Path::new(root).join("src").join("game.rs"))
                .expect("读 src/game.rs");
        let lines: Vec<&str> = src.lines().collect();
        let find = |needle: &str| -> usize {
            lines
                .iter()
                .position(|l| l.contains(needle))
                .unwrap_or_else(|| panic!("锚行缺失：{}", needle))
        };
        let t0 = find("pub fn advance_time");
        let t1 = find("self.rmodal = Some(Self::rencounter_card())");
        let t2 = find("pub fn ach_progress");
        assert!(
            t0 < t1 && t1 < t2,
            "邂逅 roll 挂 advance_time 尾段（唯一推岁口）"
        );
        // draw.rs 分派臂在位（Rencounter → choose_rencounter，rmodal_npc=None 语义）
        let dsrc =
            std::fs::read_to_string(std::path::Path::new(root).join("src").join("draw.rs"))
                .expect("读 src/draw.rs");
        assert!(
            dsrc.contains("CardKind::Rencounter) {")
                && dsrc.contains("g.choose_rencounter(i);"),
            "draw_modal_card 分派臂须单列 Rencounter"
        );
    }

    // ── G8 bug② 静态钉：鬼影标签删净 + 四真钮在位（prod() 滤 cfg(test) 照
    // comm_hooks_static_pins 先例——测试字符串自身不入扫描面） ──
    #[test]
    fn ghost_label_removed_pins() {
        let root = env!("CARGO_MANIFEST_DIR");
        let src =
            std::fs::read_to_string(std::path::Path::new(root).join("src").join("draw.rs"))
                .expect("读 src/draw.rs");
        let mut out = String::new();
        let mut skip = false;
        for line in src.lines() {
            if line.starts_with("#[cfg(test)]") {
                skip = true;
                continue;
            }
            if skip {
                if line == "}" {
                    skip = false;
                }
                continue;
            }
            out.push_str(line);
            out.push('\n');
        }
        let count = |needle: &str| out.matches(needle).count();
        // 正向钉：遗留鬼影四行删净（v1.0.0 起的第二份顶栏标签 + legacy 1.5px 钮框）
        assert_eq!(count("txt_r(\"烙印\""), 0, "鬼影「烙印」须删净");
        assert_eq!(count("txt_r(\"帮助\""), 0, "鬼影「帮助」须删净");
        assert_eq!(
            count("draw_rectangle_lines(1086.0"),
            0,
            "legacy 1.5px 烙印钮框须删净"
        );
        assert_eq!(
            count("draw_rectangle_lines(1154.0"),
            0,
            "legacy 1.5px 帮助钮框须删净"
        );
        // 反向钉：四真钮调用各恰 1（防顺手多删）
        assert_eq!(
            count("button(1018.0, 8.0, 62.0, 36.0, \"任务\""),
            1,
            "任务真钮在位"
        );
        assert_eq!(
            count("button(1086.0, 8.0, 62.0, 36.0, \"烙印\""),
            1,
            "烙印真钮在位"
        );
        assert_eq!(
            count("button(1154.0, 8.0, 62.0, 36.0, \"帮助\""),
            1,
            "帮助真钮在位"
        );
        assert_eq!(
            count("button(1222.0, 8.0, 58.0, 36.0, \"主页\""),
            1,
            "主页真钮在位"
        );
    }
}

// ================= 演出包⑰-2 底栏 stagger 双保险钉测（照 v11640/v11641 款） =================
// 行为钉：三 game.rs 置值口（begin_mortal/resume_life/finish_inherit）实调断言
// bar_anim=BAR_ANIM_T，且非触发路径（默认夹具/换幕）不置位；静态钉：五生产口
// 逐口 3 行窗结构断言（game.rs 计 3 / world.rs 计 2，照 v11641_zoom_anim_tests
// plan 数组款——漏改/错改/新增口未带计时即红；autopilot 置场非正式玩法不列计）。
// 模组名 v11646（v11645 前缀已被 v11645_comp_multi_tests 占用，按本批顺延）——
// 内容版本以本头注「演出包⑰-2」（v1.16.45 批）为准（v1.16.45 复审③补账）。
#[cfg(test)]
mod v11646_bar_anim_tests {
    use super::revenge_tests::game_with;
    use super::*;

    // ── 行为钉：三口置值 + 会话态默认 0 ──
    #[test]
    fn bar_anim_sites_set_and_default_zero() {
        // 默认夹具：会话态天然 0（旧档载入口径）
        let g = game_with(Life::default(), None);
        assert_eq!(g.bar_anim, 0.0, "会话态默认无动画");
        let mut g = game_with(Life::default(), None);
        g.begin_mortal();
        assert_eq!(g.bar_anim, BAR_ANIM_T, "begin_mortal 置值口 1/5");
        let mut g2 = game_with(Life::default(), None);
        g2.resume_life();
        assert_eq!(g2.bar_anim, BAR_ANIM_T, "resume_life 置值口 2/5");
        let mut g3 = game_with(Life::default(), None);
        g3.finish_inherit();
        assert_eq!(g3.bar_anim, BAR_ANIM_T, "finish_inherit 置值口 3/5");
    }

    // ── 静态钉：五生产口逐口 3 行窗（game.rs 计 3 / world.rs 计 2） ──
    #[test]
    fn bar_anim_sites_all_carry_anim() {
        let root = env!("CARGO_MANIFEST_DIR");
        let plan = [("game.rs", 3usize), ("world.rs", 2)];
        for (f, expect) in plan {
            let src = std::fs::read_to_string(std::path::Path::new(root).join("src").join(f))
                .unwrap_or_else(|e| panic!("读 src/{} 失败：{}", f, e));
            // prod 滤测试区（照 ghost_label_removed_pins 款——本钉自身 needle 行
            // 位于 cfg(test) 内不入扫描面，否则自计数漂移）
            let mut prod = String::new();
            let mut skip = false;
            for line in src.lines() {
                if line.starts_with("#[cfg(test)]") {
                    skip = true;
                    continue;
                }
                if skip {
                    if line == "}" {
                        skip = false;
                    }
                    continue;
                }
                prod.push_str(line);
                prod.push('\n');
            }
            let lines: Vec<&str> = prod.lines().collect();
            let mut sites = 0usize;
            for idx in 0..lines.len() {
                let l = lines[idx];
                let is_site = (f == "game.rs"
                    && (l.contains("self.bar_anim = crate::game::BAR_ANIM_T")
                        || l.contains("self.bar_anim = BAR_ANIM_T")))
                    || (f == "world.rs" && l.contains("g.bar_anim = crate::game::BAR_ANIM_T"));
                if is_site {
                    sites += 1;
                    // 置值行本身即锚（无需 3 行窗——行为钉已验值；此处断言行存在性）
                }
            }
            assert_eq!(
                sites, expect,
                "src/{} bar_anim 置值口数漂移：实得 {} 预期 {}——新增进现实行动层入口须同批带 bar_anim 置值并入本钉",
                f, sites, expect
            );
        }
    }

    // ── 稳态收敛静态钉：draw.rs 底栏相位消费行经 bar_stagger_a 单口（闭包直算式
    // 不得回归——纯函数单测前提） ──
    #[test]
    fn bar_stagger_via_pure_fn() {
        let root = env!("CARGO_MANIFEST_DIR");
        let src = std::fs::read_to_string(std::path::Path::new(root).join("src").join("draw.rs"))
            .expect("读 src/draw.rs");
        assert!(
            src.contains("let bar_a = |k: usize| bar_stagger_a(bar_e, k);"),
            "底栏相位必须经 bar_stagger_a 纯函数单口（钉测相位断言前提）"
        );
        assert!(
            !src.contains("(bar_e - k as f32 * 0.03) / 0.03).clamp"),
            "底栏相位不得退回闭包内直算式（纯函数单口纪律）"
        );
    }
}

// ================= v1.16.45 施工单三扩池段十八 + 剧情加长 + 第二十一批润色 钉测 =================
// 模组名 v11646（v11645 前缀已被 v11645_comp_multi_tests 占用，按本批顺延）——
// 内容版本以本头注 v1.16.45 为准（v1.16.45 复审③补账，照本文件 v11644 模组头与
// charpanel.rs v11646_button_fx_tests 的逐模块头注款）。
#[cfg(test)]
mod v11646_pool_tests {
    use super::revenge_tests::game_with;
    use super::*;

    fn sim_game(realm: usize, luck: f32) -> Game {
        let mut g = game_with(Life::default(), None);
        let mut s = Life::default();
        s.realm = realm;
        s.luck = luck;
        g.sim = Some(s);
        g
    }

    // ── 段十八三卡良构：id==下标连续、≥2 ≤3 选项、标题/正文非空、选首项不 panic ──
    #[test]
    fn seg18_cards_well_formed() {
        let mut g = game_with(Life::default(), None);
        g.sim = Some(Life::default());
        for id in 371..=373usize {
            assert_eq!(EVENTS_ROWS[id].0 as usize, id, "段十八 id 连续");
            g.modal = None;
            g.build_event(id);
            let card = g.modal.as_ref().unwrap();
            assert!(!card.title.is_empty(), "id {} 标题非空", id);
            assert!(!card.text.is_empty(), "id {} 正文非空", id);
            assert!(
                card.opts.len() >= 2 && card.opts.len() <= 3,
                "id {} 选项数 {} 越界",
                id,
                card.opts.len()
            );
            // v1.16.46 勘四必修①随批 wrap 行数代理钉（照③口径防回退）：tall 版式
            // max_h=120px（draw.rs 勘四必修①改后）=2+2 行恰满——每段 ≤58 字（32
            // 字/行贪心 → ≤2 行），两段合计 ≤4 行即 120px 内完整可见；段十八三卡
            // 44+40/25+46/34+47 字全在预算内（112px 旧实参下 371/373 第二段被截，
            // 修复后完整）。检查置于 choose_option 之前（card 不可变借用与 &mut
            // 不相交——借用纪律）
            let segs: Vec<&str> = card.text.split('\n').collect();
            for (seg_k, seg) in segs.iter().enumerate() {
                let n = seg.chars().count();
                assert!(
                    n <= 58,
                    "段十八 id {} 段 {} 越 58 字预算（tall 120px=2+2 行代理）: {} ({}字)",
                    id,
                    seg_k,
                    seg,
                    n
                );
            }
            g.choose_option(0); // apply_eff 全链不 panic（sync_save 仅置脏不落盘）
        }
    }

    // ── 段十八权重/门控钉：三行 (id,w,mr,good) 表钉 + realm 达标入池抽验 ──
    #[test]
    fn seg18_weight_and_gate_pins() {
        assert_eq!(
            EVENTS_ROWS[371],
            (371, 3, 7, false),
            "371 牒案翻旧=mr7 恶（恶缘 mr7 层最薄缺口）"
        );
        assert_eq!(
            EVENTS_ROWS[372],
            (372, 3, 6, true),
            "372 堂前领差=mr6 善+玄诚 Npc(0)"
        );
        assert_eq!(
            EVENTS_ROWS[373],
            (373, 3, 5, true),
            "373 残页对笔=mr5 善"
        );
        // 入池抽验（照 companion_events_gated_by_companion 直调式）：realm≥mr 入池
        let g = sim_game(7, 100.0);
        let (ws, _) = g.sim_event_weights(100.0, 7, false, false, false);
        for id in [371usize, 372, 373] {
            assert!(ws[id] > 0.0, "realm7 时事件 {} 应入池", id);
        }
        // mr 门控下限抽验：realm5 时 371（mr7）不入池
        let g2 = sim_game(5, 100.0);
        let (ws2, _) = g2.sim_event_weights(100.0, 5, false, false, false);
        assert_eq!(ws2[371], 0.0, "realm5 时 mr7 卡不入池");
        // 卡面主角同源钉：372 正文钉名⟺Npc(0)（照 337 区纪律）
        let mut g3 = game_with(Life::default(), None);
        g3.sim = Some(Life::default());
        g3.modal = None;
        g3.build_event(372);
        let c = g3.modal.as_ref().unwrap();
        assert!(
            matches!(c.actor, Some(CardActor::Npc(0))),
            "372 卡面主角须玄诚 Npc(0)"
        );
        assert!(c.text.contains("玄诚长老"), "372 正文钉名⟺Npc(0) 同源");
        // ③口径钉：三卡正文 2 段（反斜杠 n 分段——剧情加长直改面，防回退单段）
        for id in 371..=373usize {
            g3.modal = None;
            g3.build_event(id);
            let t = &g3.modal.as_ref().unwrap().text;
            assert!(t.contains('\n'), "id {} 正文须 2 段（剧情加长③口径）", id);
            // 2 段各 ≤58 字（tall 版式 4 wrap 行预算代理——字数钉+打包目检兜底）
            let segs: Vec<&str> = t.split('\n').collect();
            assert_eq!(segs.len(), 2, "id {} 段数须恰 2", id);
            for (k, seg) in segs.iter().enumerate() {
                let n = seg.chars().count();
                assert!(
                    n <= 58,
                    "id {} 段 {} 越 58 字预算: {} ({}字)",
                    id,
                    k,
                    seg,
                    n
                );
            }
        }
    }

    // ── 第二十一批简语润色（batch25）：want 逐字 + ≤18 + kw 保词（照 batch24 款）──
    #[test]
    fn event_brief_11646_batch25_polish_within_18() {
        for (id, want, kw) in [
            (242usize, "新渠按契分水，旧约压案头", "旧约"),   // N1353，kw 既有钉保词
            (238, "单子出了损，手印找上门", "手印"),          // N1349，kw 臂 verbatim
            (194, "仙籍册另有个你，在北域行医", "北域"),      // N1305，kw 既有钉保词
            (193, "后辈摆证道台，请不动前辈", "证道台"),      // N1304，kw 臂 verbatim
            (180, "云阶千级，拾级或阶下观人", "云阶"),        // N1291，kw 臂 verbatim
            (175, "雨夜伞铺，老匠只修凡伞", "凡伞"),          // N1286，kw 臂 verbatim
            (166, "官册空一格野地，草高过批注", "官册"),      // N1277，kw 既有钉保词
            (161, "白鹿踏雪过涧，循迹或长揖", "白鹿"),        // N1272，kw 臂 verbatim
            (152, "循存根到药庐，赎箫或止步", "存根"),        // N1263，kw 臂 verbatim
            (110, "宿敌倾巢寻账，火把围谷", "火把"),          // N1221，kw 既有钉保词
        ] {
            let b = &EVENT_BRIEF[id];
            let n = b.chars().count();
            assert_eq!(b, want, "事件 {} 简语改写漂移（第二十一批润色）", id);
            assert!(
                !b.is_empty() && n <= 18,
                "事件 {} 简越 18 字预算: {} ({}字)",
                id,
                b,
                n
            );
            assert!(b.contains(kw), "事件 {} 简画面化改写漂移: {}", id, b);
        }
    }

    // ── 章节引子加长预算钉（剧情加长主案①方案 A：intro 原地直改——下界防回退
    // 旧短文、上界防穿 4 行版式（draw.rs 章节书 intro wrap 600px ≤4 行≈37 字/行
    // ×4=148 字预算）） ──
    #[test]
    fn chapter_intro_prelude_budget() {
        assert_eq!(CHAPTERS.len(), 9);
        // 循环变量照仓内 k 惯例（勿用 i——施工单五收尾纪律复核逮住照抄先例的 i）
        for (k, ch) in CHAPTERS.iter().enumerate() {
            let n = ch.intro().chars().count();
            assert!(
                (100..=148).contains(&n),
                "章 {} intro 越加长预算 [100,148]: {} ({}字)——上界防穿 4 行版式、下界防回退旧短文",
                k,
                ch.intro(),
                n
            );
        }
    }
}

// ================= v1.16.46 段十九扩池（三纸同檐/同页生隙/空阶一蝶）钉测 =================
// 模组名注：v11645 前缀已被 v11645_comp_multi_tests 占用、v11646 前缀已被
// v11646_bar_anim/v11646_pool/v11646_button_fx 三模组占用，本批钉测模块名顺延
// v11647，内容版本以本头注 v1.16.46 为准（照本文件 v11644 模组头与 charpanel.rs
// v11646_button_fx_tests 的逐模块头注款）。
// 钉面：①段十九三卡良构（id 连续/w3 A 案/标题双源/≥2 选项/2 段 ≤58 字/rare=false
// stage None/374 副伴立绘反查同源）②374 副伴门控行为钉（主伴在场而副伴位空仍
// 0——白名单口径反证；有副伴入池；375/376 免门控各按 mr 层入池）③门控分支静态
// 钉（comp_extra.is_empty() 恰 1 处在 prod 区防误删防改白名单口径）
#[cfg(test)]
mod v11647_seg19_tests {
    use super::revenge_tests::game_with;
    use super::*;

    fn sim_game(realm: usize, luck: f32) -> Game {
        let mut g = game_with(Life::default(), None);
        let mut s = Life::default();
        s.realm = realm;
        s.luck = luck;
        g.sim = Some(s);
        g
    }

    // ── 段十九三卡良构（照 seg18_cards_well_formed 款） ──
    #[test]
    fn seg19_cards_well_formed() {
        let mut g = game_with(Life::default(), None);
        g.sim = Some(Life::default());
        for id in 374..=376usize {
            assert_eq!(EVENTS_ROWS[id].0 as usize, id, "段十九 id 连续");
            assert_eq!(EVENTS_ROWS[id].1, 3, "段十九 id {} 基权 w3（A 案）", id);
            g.modal = None;
            g.build_event(id);
            let card = g.modal.as_ref().unwrap();
            assert_eq!(card.title, EVENT_NAMES[id], "标题双源 id {}", id);
            assert!(!card.text.is_empty());
            assert!(card.opts.len() >= 2, "事件 {} 至少两选项", id);
            assert!(!card.rare, "id {} A 案 w3 不入稀有", id);
            assert!(card.stage.is_none(), "id {} 散件 stage 恒 None", id);
            // ③口径钉：正文 2 段各 ≤58 字（tall max_h=120px=2+2 行代理，照
            // seg18 勘四必修①随批款）
            let segs: Vec<&str> = card.text.split('\n').collect();
            assert_eq!(segs.len(), 2, "id {} 段数须恰 2", id);
            for (k, seg) in segs.iter().enumerate() {
                let n = seg.chars().count();
                assert!(
                    n <= 58,
                    "id {} 段 {} 越 58 字预算: {} ({}字)",
                    id,
                    k,
                    seg,
                    n
                );
            }
        }
        // 副伴卡立绘同源钉：374 立绘=副伴反查⟺正文含副伴名（照 357/G7 款）
        let mut g2 = sim_game(3, 100.0);
        if let Some(s) = g2.sim.as_mut() {
            s.companion = Some(COMPANION_NAMES[0].to_string());
            s.comp_extra = vec![COMPANION_NAMES[3].to_string()];
        }
        g2.modal = None;
        g2.build_event(374);
        let card = g2.modal.as_ref().unwrap();
        if let Some(CardActor::Comp(xi)) = card.actor {
            assert_eq!(
                COMPANION_NAMES[xi], COMPANION_NAMES[3],
                "374 立绘须为副伴反查"
            );
            assert!(
                card.text.contains(COMPANION_NAMES[3])
                    && card.text.contains(COMPANION_NAMES[0]),
                "374 正文须含副伴与主伴名"
            );
        } else {
            panic!("374 须挂 Comp 副伴立绘（零新立绘红线）");
        }
    }

    // ── 374 副伴门控行为钉 ──
    #[test]
    fn seg19_extra_comp_gate() {
        // 主伴在场而副伴位空：ws[374]==0（白名单口径反证——门在 comp_extra）
        let mut g = sim_game(3, 100.0);
        if let Some(s) = g.sim.as_mut() {
            s.companion = Some(COMPANION_NAMES[0].to_string());
        }
        let (ws, _) = g.sim_event_weights(100.0, 3, false, false, true);
        assert_eq!(
            ws[374], 0.0,
            "主伴在场而副伴位空 → 374 不入池（comp_extra 门）"
        );
        // 补上副伴：入池
        if let Some(s) = g.sim.as_mut() {
            s.comp_extra = vec![COMPANION_NAMES[3].to_string()];
        }
        let (ws2, _) = g.sim_event_weights(100.0, 3, false, false, true);
        assert!(ws2[374] > 0.0, "有副伴 → 374 入池");
        // 无任何伴：不入池（副伴更无从谈起）
        let g3 = sim_game(3, 100.0);
        let (ws3, _) = g3.sim_event_weights(100.0, 3, false, false, false);
        assert_eq!(ws3[374], 0.0, "无伴 → 374 不入池");
        // 375/376 免门控（指无伴/副伴条件；mr 层门照常）：各按自身 mr 层入池
        let g7 = sim_game(7, 100.0);
        let (ws7, _) = g7.sim_event_weights(100.0, 7, false, false, false);
        assert!(ws7[375] > 0.0, "375 无门控 mr7 层入池");
        let g4 = sim_game(4, 100.0);
        let (ws4, _) = g4.sim_event_weights(100.0, 4, false, false, false);
        assert!(ws4[376] > 0.0, "376 无门控 mr4 层入池");
    }

    // ── 门控分支静态钉：comp_extra 门单点在 prod 区（防误删/防改白名单口径） ──
    #[test]
    fn seg19_extra_gate_static() {
        let root = env!("CARGO_MANIFEST_DIR");
        let src =
            std::fs::read_to_string(std::path::Path::new(root).join("src").join("game.rs"))
                .expect("读 src/game.rs");
        // prod 滤测试区（照 comm_hooks_static_pins prod() 款：行首 #[cfg(test)]
        // 起至行首顶格 } 止——本钉自身字面量不入扫描面）
        let mut prod = String::new();
        let mut skip = false;
        for line in src.lines() {
            if line.starts_with("#[cfg(test)]") {
                skip = true;
                continue;
            }
            if skip {
                if line == "}" {
                    skip = false;
                }
                continue;
            }
            prod.push_str(line);
            prod.push('\n');
        }
        let k = prod.matches("s.comp_extra.is_empty()").count();
        assert_eq!(
            k, 1,
            "374 副伴门 comp_extra.is_empty() 须恰 1 处在 prod 区（实得 {}）",
            k
        );
        assert!(
            prod.contains(
                "if id == 374 && self.sim.as_ref().map_or(true, |s| s.comp_extra.is_empty())"
            ),
            "374 门控行原样在位（防改白名单口径）"
        );
    }
}

// ================= v1.16.46 加载速度优化（施工单三/勘察一提名①②）钉测 =================
// 模组名注：v11645 前缀已被 v11645_comp_multi_tests 占用、v11646 前缀已被
// v11646_bar_anim/v11646_pool/v11646_button_fx 三模组占用，本批钉测模块名顺延
// v11647（与 v11647_seg19_tests 同批双模组、各自头注照逐模块头注款），内容版本
// 以本头注 v1.16.46 为准。
// 钉面：①双资产 miniz 对口件级 guard——产侧 zopfli 换压缩器后运行时
// miniz_oxide::inflate 必须逐位还原（font: 解压==assets/font.ttf 逐位，fontdue
// 解析面由 draw.rs banner_charset_kerning_zero 同文件钉互补；textpack: 解压非空，
// 查表面由 textpack_inflate_and_spot_check 覆盖）②boot 提名①静态钉——wasm 路径
// init_art 先于 textpack 轮询块、桌面路径原序保持（init_text 之后 cfg(not) 守卫）
// ③art 红线守卫——art.rs 运行时区零 evtx/evf（TEXT_BLOB OnceLock 抢坑红线，
// main.rs:199-202 语义的常驻看守）。
#[cfg(test)]
mod v11647_loadspeed_tests {

    // ── 双资产 miniz 对口钉（加载优化②件级 guard）──
    #[test]
    fn loadspeed_assets_miniz_roundtrip() {
        let root = env!("CARGO_MANIFEST_DIR");
        // 字体：miniz_oxide inflate（真运行 ui.rs init_font_from_bytes 同款解压口）
        // 解压必须逐位 == assets/font.ttf（产侧 make_font.py 回环自检 + 本钉双保险）
        let defl = std::fs::read(std::path::Path::new(root).join("assets/font.ttf.deflate"))
            .expect("缺 assets/font.ttf.deflate");
        let ttf = std::fs::read(std::path::Path::new(root).join("assets/font.ttf"))
            .expect("缺 assets/font.ttf");
        let back = miniz_oxide::inflate::decompress_to_vec(&defl)
            .unwrap_or_else(|e| panic!("font.ttf.deflate miniz inflate 失败：{:?}", e));
        assert_eq!(back, ttf, "font deflate 解压与 font.ttf 逐位不一致（产侧换压缩器须重跑 make_font.py）");
        assert!(back.len() > 4 && back[0] == 0 && back[1] == 1, "解压首字节非 TTF 魔数");
        // 文本包：容器对口（查表内容级由 textpack_inflate_and_spot_check 覆盖）
        let pk = std::fs::read(std::path::Path::new(root).join("assets/textpack.bin"))
            .expect("缺 assets/textpack.bin");
        let pb = miniz_oxide::inflate::decompress_to_vec(&pk)
            .unwrap_or_else(|e| panic!("textpack.bin miniz inflate 失败：{:?}", e));
        assert!(!pb.is_empty(), "textpack 解压空");
    }

    // ── boot 提名①静态钉 + art 红线守卫 ──
    #[test]
    fn boot_art_order_static() {
        let root = env!("CARGO_MANIFEST_DIR");
        let src = std::fs::read_to_string(std::path::Path::new(root).join("src").join("main.rs"))
            .expect("读 src/main.rs");
        let lines: Vec<&str> = src.lines().collect();
        // 语句级定位：trim 后恰为 art::init_art(); 的行（注释内散文不入扫描面）
        let sites: Vec<usize> = lines
            .iter()
            .enumerate()
            .filter(|(_, l)| l.trim() == "art::init_art();")
            .map(|(k, _)| k)
            .collect();
        assert_eq!(sites.len(), 2, "main.rs art::init_art(); 调用口须恰 2 处（wasm 提前 + 桌面原序）");
        let first = sites[0];
        let last = sites[1];
        // 提前口：wasm cfg 守卫 + 先于 textpack 轮询块首行
        assert!(
            lines[first - 1].trim().starts_with("#[cfg(target_arch = \"wasm32\")]"),
            "提前口须带 wasm cfg 守卫（防误挪桌面路径）"
        );
        let poll = lines
            .iter()
            .position(|l| l.contains("xx_text::len()"))
            .unwrap_or_else(|| panic!("textpack 轮询块缺失"));
        assert!(
            first < poll,
            "wasm 提名①：init_art 须先于 textpack 轮询块（与网络等待重叠）"
        );
        // 桌面口：cfg(not) 守卫 + 原序（init_text 之后）
        assert!(
            lines[last - 1].trim().starts_with("#[cfg(not(target_arch"),
            "桌面口须带 cfg(not(wasm32)) 守卫（保持桌面原序零改动）"
        );
        let init_text = lines
            .iter()
            .position(|l| l.trim() == "data::init_text();")
            .unwrap_or_else(|| panic!("data::init_text(); 语句缺失"));
        assert!(init_text < last, "桌面 init_art 原序保持（init_text 之后）");
        // 红线守卫：art.rs 运行时区（滤 cfg(test) 照 comm_hooks prod() 款）零
        // evtx/evf——TEXT_BLOB OnceLock 抢坑红线的常驻看守
        let art_src = std::fs::read_to_string(std::path::Path::new(root).join("src").join("art.rs"))
            .expect("读 src/art.rs");
        let mut prod = String::new();
        let mut skip = false;
        for line in art_src.lines() {
            if line.starts_with("#[cfg(test)]") {
                skip = true;
                continue;
            }
            if skip {
                if line == "}" {
                    skip = false;
                }
                continue;
            }
            prod.push_str(line);
            prod.push('\n');
        }
        assert!(
            !prod.contains("evtx") && !prod.contains("evf("),
            "art.rs 运行时区不得引用 evtx/evf（TEXT_BLOB OnceLock 抢坑红线——init_art 先于 textpack 装载的前提）"
        );
    }
}

// ================= v1.16.46 多道侣 UI 完善（勘察六提名一/二）钉测 =================
// 模组名注：v11645/v11646/v11647 前缀均已被占用（同 draw.rs v11648 模组头注缘
// 由），本批钉测模块名顺延 v11648，内容版本以本头注 v1.16.46 为准。
// 钉面：①comp_row_tag 行标单源行为钉（单伴态零稳态变化/多伴态主副分化/满编态
// 全粒序）+comp_full 满编口径②满编预告行/N2831/两消费点/prewarm 样例串静态钉
// ③N2831 真相源内容级逐字钉（本行不入任何 EvTable 段，tables_recheck 无看守——
// 本钉即该行内容级防线）。
#[cfg(test)]
mod v11648_comp_ui_tests {
    use super::*;

    // ── comp_row_tag 行标单源行为钉 + comp_full 满编口径 ──
    #[test]
    fn comp_row_tag_single_source() {
        let mut s = Life::default();
        // 无伴/单伴态：恒旧文「此生同页」（勘察六取舍声明——绝对零稳态变化款）
        assert_eq!(s.comp_row_tag(0), "此生同页", "无伴态恒旧文");
        s.companion = Some(COMPANION_NAMES[0].to_string());
        assert_eq!(s.comp_row_tag(0), "此生同页", "单伴态主伴行零稳态变化");
        // 多伴态：主伴「此生主页」/副伴「此生同页」（v1.16.45 新态无旧稳态包袱）
        s.comp_extra = vec![COMPANION_NAMES[3].to_string()];
        assert_eq!(s.comp_row_tag(0), "此生主页", "多伴态主伴行标");
        assert_eq!(s.comp_row_tag(3), "此生同页", "多伴态副伴行标");
        // 满编态（主伴+2 副伴）：主伴主页、两副伴同页 + comp_full 口径（FIFO 预告
        // 行前置条件——非满编零追加）
        s.comp_extra = vec![COMPANION_NAMES[3].to_string(), COMPANION_NAMES[7].to_string()];
        assert!(s.comp_full(), "主伴+2 副伴=满编（COMP_MAX=3）");
        assert_eq!(s.comp_row_tag(0), "此生主页");
        assert_eq!(s.comp_row_tag(3), "此生同页");
        assert_eq!(s.comp_row_tag(7), "此生同页");
        let mut s2 = Life::default();
        s2.companion = Some(COMPANION_NAMES[0].to_string());
        s2.comp_extra = vec![COMPANION_NAMES[3].to_string()];
        assert!(!s2.comp_full(), "主伴+1 副伴未满编");
    }

    // ── 静态钉：预告行/两消费点/prewarm 样例串 + N2831 内容级逐字钉 ──
    #[test]
    fn comp_ui_static_pins() {
        let root = env!("CARGO_MANIFEST_DIR");
        let prod_of = |fname: &str| -> String {
            let src = std::fs::read_to_string(std::path::Path::new(root).join("src").join(fname))
                .unwrap_or_else(|e| panic!("读 src/{} 失败：{}", fname, e));
            let mut out = String::new();
            let mut skip = false;
            for line in src.lines() {
                if line.starts_with("#[cfg(test)]") {
                    skip = true;
                    continue;
                }
                if skip {
                    if line == "}" {
                        skip = false;
                    }
                    continue;
                }
                out.push_str(line);
                out.push('\n');
            }
            out
        };
        let char_p = prod_of("charpanel.rs");
        assert_eq!(
            char_p.matches("let fifo_warn = l").count(),
            1,
            "满编预告行口恰 1（comp_full 门控——非满编零追加）"
        );
        assert_eq!(
            char_p.matches("evf(2831, &[&(nm) as &dyn core::fmt::Display])").count(),
            1,
            "N2831 满编预告消费恰 1（charpanel 副伴行尾）"
        );
        assert_eq!(
            char_p.matches("s.comp_row_tag(i)").count(),
            1,
            "charpanel 缘谱行标走 comp_row_tag 单口"
        );
        assert_eq!(
            char_p.matches("evf(2831, &[&COMPANION_NAMES[0] as &dyn core::fmt::Display])")
                .count(),
            1,
            "prewarm N2831 静态字集样例串恰 1（@14 防首开冷栅格化）"
        );
        let gal_p = prod_of("gallery.rs");
        assert_eq!(
            gal_p.matches("s.comp_row_tag(i)").count(),
            1,
            "gallery 图鉴卡行标走 comp_row_tag 单口（两消费点同批勿半改）"
        );
        let game_p = prod_of("game.rs");
        assert_eq!(
            game_p.matches("pub fn comp_row_tag").count(),
            1,
            "行标判定单口恰 1（Life::comp_row_tag）"
        );
        // N2831 内容级逐字钉：本行不入任何 EvTable 段（名段止 2818/简段止 2821），
        // tables_recheck 无看守——逐字对账即该行唯一内容级防线
        let src_txt = std::fs::read_to_string(std::path::Path::new(root).join("assets/text_source.txt"))
            .expect("读 assets/text_source.txt");
        let n2831 = src_txt
            .lines()
            .find(|l| l.starts_with("2831\t"))
            .unwrap_or_else(|| panic!("真相源缺 N2831 行（满编预告文案）"));
        assert_eq!(
            n2831.trim_end_matches('\r'),
            "2831\t再缝则{}页渐疏",
            "N2831 内容漂移（与 charpanel 原文注/占位符数联动）"
        );
    }
}

// ================= v1.16.47 段二十扩池（晒书使巡/巷尾淘井/夜渡加价）钉测 =================
// 模组名注：v11645 前缀已被 v11645_comp_multi_tests 占用、v11646 前缀已被
// v11646_bar_anim/v11646_pool/v11646_button_fx 三模组占用、v11647 前缀已被
// v11647_seg19/v11647_loadspeed 两模组占用、v11648 前缀已被 v11648_brk_veil/
// v11648_bond_rite（draw.rs 两）/v11648_button_jewel（charpanel.rs）/v11648_comp_ui
// 四模组占用，本批钉测模块名顺延 v11649，内容版本以本头注 v1.16.47 为准（照
// v11647_seg19_tests 逐模块头注款）。
// 钉面：①段二十三卡良构（id 连续/A 案 377 w1 入稀有+378/379 w3/标题双源/≥2 选
// 项/正文 2 段 ≤58 字/377 检定 opt 特殊位 special78+零 msg 照 369 款/379 石罚负值
// 照 375 款/stage 恒 None）②三卡各按 mr 层入池+377 无门控（对照 374 副伴门仍在）
// ③special78 检定接线静态钉（build_event e1.special=78 恰 1/apply_eff 过败 slog
// N2841/N2842 单口/SPECIAL_SUB 表长 79）+N2838 副标手写行真相源逐字钉（不入
// EvTable 段、tables_recheck 无看守——照 N2831 口径即唯一内容级防线）
#[cfg(test)]
mod v11649_seg20_tests {
    use super::revenge_tests::game_with;
    use super::*;

    fn sim_game(realm: usize, luck: f32) -> Game {
        let mut g = game_with(Life::default(), None);
        let mut s = Life::default();
        s.realm = realm;
        s.luck = luck;
        g.sim = Some(s);
        g
    }

    // ── 段二十三卡良构（照 seg19_cards_well_formed 款，377 检定卡按 369 款分断） ──
    #[test]
    fn seg20_cards_well_formed() {
        let mut g = game_with(Life::default(), None);
        g.sim = Some(Life::default());
        for id in 377..=379usize {
            assert_eq!(EVENTS_ROWS[id].0 as usize, id, "段二十 id 连续");
            let want_w = if id == 377 { 1 } else { 3 };
            assert_eq!(EVENTS_ROWS[id].1, want_w, "段二十 id {} 基权（A 案）", id);
            g.modal = None;
            g.build_event(id);
            let card = g.modal.as_ref().unwrap();
            assert_eq!(card.title, EVENT_NAMES[id], "标题双源 id {}", id);
            assert!(!card.text.is_empty());
            assert!(card.opts.len() >= 2, "事件 {} 至少两选项", id);
            assert_eq!(
                card.rare,
                id == 377,
                "id {} rare 口径（377 检定 w1 照 369 款）",
                id
            );
            assert!(card.stage.is_none(), "id {} stage 恒 None（非链段）", id);
            // ③口径钉：正文 2 段各 ≤58 字（tall max_h=120px=2+2 行代理，照
            // seg18/seg19 勘四必修①随批款）
            let segs: Vec<&str> = card.text.split('\n').collect();
            assert_eq!(segs.len(), 2, "id {} 段数须恰 2", id);
            for (k, seg) in segs.iter().enumerate() {
                let n = seg.chars().count();
                assert!(
                    n <= 58,
                    "id {} 段 {} 越 58 字预算: {} ({}字)",
                    id,
                    k,
                    seg,
                    n
                );
            }
        }
        // 377 检定 opt 特征（照 369 款：opt1 检定零 msg 零文案行/opt2 善散件 msg 一行）
        g.modal = None;
        g.build_event(377);
        let card = g.modal.as_ref().unwrap();
        assert_eq!(card.opts[0].1.special, 78, "377 opt1 检定位 special78");
        assert!(card.opts[0].1.msg.is_empty(), "377 opt1 检定零 msg（照 369 款）");
        assert_eq!(card.opts[0].1.good, false, "377 opt1 good=false 照 369 e1 款");
        assert!(
            card.opts[1].1.special == 0 && !card.opts[1].1.msg.is_empty(),
            "377 opt2 善散件 msg 一行"
        );
        // 379 石罚负值特征（照 375 mr7 案值厚款）
        g.modal = None;
        g.build_event(379);
        let card = g.modal.as_ref().unwrap();
        assert!(card.opts[0].1.stones < 0, "379 opt1 石罚负值");
    }

    // ── 三卡入池行为钉：各按 mr 层入池 + 377 无门控（对照 374 副伴门仍在） ──
    #[test]
    fn seg20_pool_gates() {
        // 377 mr2 层（sim realm 2）无门控：无伴也入池
        let g2 = sim_game(2, 100.0);
        let (ws2, _) = g2.sim_event_weights(100.0, 2, false, false, false);
        assert!(ws2[377] > 0.0, "377 无门控 mr2 层入池");
        // 378 mr6 层
        let g6 = sim_game(6, 100.0);
        let (ws6, _) = g6.sim_event_weights(100.0, 6, false, false, false);
        assert!(ws6[378] > 0.0, "378 无门控 mr6 层入池");
        // 379 mr7 层
        let g7 = sim_game(7, 100.0);
        let (ws7, _) = g7.sim_event_weights(100.0, 7, false, false, false);
        assert!(ws7[379] > 0.0, "379 无门控 mr7 层入池");
        // 对照：374 副伴门仍在（主伴在场副伴位空 → 0）——本批零新增门控旁证
        let mut g3 = sim_game(3, 100.0);
        if let Some(s) = g3.sim.as_mut() {
            s.companion = Some(COMPANION_NAMES[0].to_string());
        }
        let (ws3, _) = g3.sim_event_weights(100.0, 3, false, false, true);
        assert_eq!(ws3[374], 0.0, "374 副伴门仍在（本批未动既有门控）");
    }

    // ── special78 检定接线静态钉 + N2838 副标手写行逐字钉 ──
    #[test]
    fn seg20_check_pin_static() {
        let root = env!("CARGO_MANIFEST_DIR");
        let src =
            std::fs::read_to_string(std::path::Path::new(root).join("src").join("game.rs"))
                .expect("读 src/game.rs");
        // prod 滤测试区（照 seg19_extra_gate_static prod() 款：行首 #[cfg(test)]
        // 起至行首顶格 } 止——本钉自身字面量不入扫描面）
        let mut prod = String::new();
        let mut skip = false;
        for line in src.lines() {
            if line.starts_with("#[cfg(test)]") {
                skip = true;
                continue;
            }
            if skip {
                if line == "}" {
                    skip = false;
                }
                continue;
            }
            prod.push_str(line);
            prod.push('\n');
        }
        assert_eq!(
            prod.matches("e1.special = 78;").count(),
            1,
            "special78 构建口恰 1（build_event 377 检定 opt）"
        );
        assert_eq!(
            prod.matches("evtx(2841)").count(),
            1,
            "apply_eff 78 过臂 slog N2841 单口"
        );
        assert_eq!(
            prod.matches("evtx(2842)").count(),
            1,
            "apply_eff 78 败臂 slog N2842 单口"
        );
        // v1.16.53 段二十六扩池随批：表长钉 80→81（special80 启用；旧 80 断言
        // 随批改写照 v1.16.50 改差兑现先例）
        assert_eq!(
            prod.matches("const SPECIAL_SUB: [u16; 81]").count(),
            1,
            "SPECIAL_SUB 表长 81（槽 80 启用）恰 1"
        );
        // N2838 副标手写行逐字钉：本行不入任何 EvTable 段（名段止 2834/简段止
        // 2837），tables_recheck 无看守——逐字对账即该行唯一内容级防线（照
        // N2831 comp_ui_static_pins 款）
        let src_txt = std::fs::read_to_string(
            std::path::Path::new(root)
                .join("assets")
                .join("text_source.txt"),
        )
        .expect("读 assets/text_source.txt");
        let n2838 = src_txt
            .lines()
            .find(|l| l.starts_with("2838\t"))
            .unwrap_or_else(|| panic!("真相源缺 N2838 行（检定副标手写文案）"));
        assert_eq!(
            n2838.trim_end_matches('\r'),
            "2838\t卷面候勘",
            "N2838 内容漂移（与 SPECIAL_SUB 槽 78/N2839 正文联动）"
        );
    }
}

